#[test]
fn slang_project_manifest_compiles_library_resolved_modules() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("project-manifest");
    let library = root.join("lib");
    std::fs::create_dir_all(&library).expect("create project library");
    std::fs::write(
        library.join("project_child.sv"),
        r#"
module project_child(input logic a, output logic y);
assign y = a;
endmodule
"#,
    )
    .expect("write library module");
    std::fs::write(
        root.join("project_top.sv"),
        r#"
module project_top(input logic a, output logic y);
project_child child(.a(a), .y(y));
endmodule
"#,
    )
    .expect("write project top");
    std::fs::write(
        library.join("unused_helper.sv"),
        r#"
module unused_helper();
endmodule
"#,
    )
    .expect("write unselected library module");
    let manifest_path = root.join("project.json");
    std::fs::write(
        &manifest_path,
        r#"
{
  "top": "project_top",
  "sources": ["project_top.sv"],
  "library_directories": ["lib"],
  "library_extensions": [".sv"]
}
"#,
    )
    .expect("write project manifest");

    let design = slang
        .compile_project_manifest(&manifest_path)
        .expect("compile library-aware project manifest");
    assert_eq!(design.name, "project_top");
    assert_eq!(design.hierarchy.len(), 2);
    assert!(
        design
            .hierarchy
            .iter()
            .any(|instance| instance.module == "project_child"),
        "library child was not flattened: {:?}",
        design
            .hierarchy
            .iter()
            .map(|instance| instance.module.clone())
            .collect::<Vec<_>>()
    );

    let second = slang
        .compile_project_manifest(&manifest_path)
        .expect("repeat library-aware project compilation");
    assert_eq!(second.hierarchy.len(), design.hierarchy.len());
    assert_eq!(
        slang
            .ast_cache_stats()
            .expect("library project cache statistics"),
        eda_slang::SlangAstCacheStats {
            hits: 1,
            misses: 1,
            insertions: 1,
            evictions: 0,
            entries: 1,
        },
        "selected library file contents must participate in the AST cache key"
    );

    std::fs::write(
        library.join("project_child.sv"),
        r#"
module project_child(input logic a, output logic y);
assign y = !a;
endmodule
"#,
    )
    .expect("change selected library module");
    let changed = slang
        .compile_project_manifest(&manifest_path)
        .expect("compile after selected library module changed");
    assert_eq!(changed.hierarchy.len(), design.hierarchy.len());
    assert_eq!(
        slang
            .ast_cache_stats()
            .expect("changed library project cache statistics"),
        eda_slang::SlangAstCacheStats {
            hits: 1,
            misses: 2,
            insertions: 2,
            evictions: 0,
            entries: 2,
        }
    );

    std::fs::write(
        library.join("new_candidate.sv"),
        r#"
module new_candidate();
endmodule
"#,
    )
    .expect("add library candidate");
    slang
        .compile_project_manifest(&manifest_path)
        .expect("compile after library inventory changed");
    assert_eq!(
        slang
            .ast_cache_stats()
            .expect("library inventory cache statistics"),
        eda_slang::SlangAstCacheStats {
            hits: 1,
            misses: 3,
            insertions: 2,
            evictions: 0,
            entries: 2,
        }
    );
}

#[test]
fn slang_project_manifest_reuses_and_invalidates_persistent_cache() {
    let Some(initial_frontend) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("persistent-project-cache");
    let library = root.join("lib");
    let cache = root.join("cache");
    std::fs::create_dir_all(&library).expect("create persistent project library");
    std::fs::write(
        library.join("persistent_child.sv"),
        r#"
module persistent_child(input logic a, output logic y);
assign y = a;
endmodule
"#,
    )
    .expect("write persistent library child");
    std::fs::write(
        root.join("persistent_top.sv"),
        r#"
module persistent_top(input logic a, output logic y);
persistent_child child(.a(a), .y(y));
endmodule
"#,
    )
    .expect("write persistent top");
    let manifest_path = root.join("project.json");
    std::fs::write(
        &manifest_path,
        r#"
{
  "top": "persistent_top",
  "sources": ["persistent_top.sv"],
  "library_directories": ["lib"],
  "library_extensions": [".sv"]
}
"#,
    )
    .expect("write persistent project manifest");

    let first = initial_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("first persistent project compile");
    assert!(!first.cache_hit);
    assert_eq!(
        first
            .rebuilt_units
            .iter()
            .cloned()
            .collect::<std::collections::BTreeSet<_>>(),
        std::collections::BTreeSet::from([
            "persistent_child".to_string(),
            "persistent_top".to_string(),
        ])
    );
    assert_eq!(first.design.name, "persistent_top");
    assert!(cache.join("record.json").is_file());
    assert!(cache.join("ast.json").is_file());
    let unit_files = std::fs::read_dir(cache.join("units"))
        .expect("persistent unit cache directory exists")
        .map(|entry| entry.expect("read persistent unit artifact").path())
        .collect::<Vec<_>>();
    assert_eq!(unit_files.len(), 2, "{unit_files:?}");
    let unit_names = unit_files
        .iter()
        .map(|path| {
            let artifact = serde_json::from_str::<serde_json::Value>(
                &std::fs::read_to_string(path).expect("read persistent unit artifact"),
            )
            .expect("parse persistent unit artifact");
            artifact
                .get("name")
                .and_then(serde_json::Value::as_str)
                .expect("persistent unit name")
                .to_string()
        })
        .collect::<std::collections::BTreeSet<_>>();
    assert_eq!(
        unit_names,
        std::collections::BTreeSet::from([
            "persistent_child".to_string(),
            "persistent_top".to_string(),
        ])
    );
    let child_artifact = unit_files
        .iter()
        .find(|path| {
            let artifact = serde_json::from_str::<serde_json::Value>(
                &std::fs::read_to_string(path).expect("read child artifact candidate"),
            )
            .expect("parse child artifact candidate");
            artifact.get("name").and_then(serde_json::Value::as_str) == Some("persistent_child")
        })
        .expect("persistent child artifact path");
    let top_artifact = unit_files
        .iter()
        .find(|path| {
            let artifact =
                serde_json::from_str::<serde_json::Value>(&std::fs::read_to_string(path).unwrap())
                    .unwrap();
            artifact.get("name").and_then(serde_json::Value::as_str) == Some("persistent_top")
        })
        .expect("persistent top artifact path");
    let top_artifact =
        serde_json::from_str::<serde_json::Value>(&std::fs::read_to_string(top_artifact).unwrap())
            .unwrap();
    let nested_child = top_artifact
        .get("body")
        .and_then(|body| body.get("members"))
        .and_then(serde_json::Value::as_array)
        .unwrap()
        .iter()
        .find(|member| member.get("kind").and_then(serde_json::Value::as_str) == Some("Instance"))
        .unwrap();
    assert!(
        nested_child
            .get("body")
            .and_then(|body| body.get("members"))
            .is_none(),
        "top unit artifact must prune nested child members"
    );

    let second_frontend = discover_slang_for_tests().expect("rediscover pinned slang");
    let second = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("second persistent project compile");
    assert!(second.cache_hit);
    assert_eq!(second.design.name, first.design.name);
    assert_eq!(second.design.hierarchy.len(), first.design.hierarchy.len());
    let artifact_cached = second_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("lower reconstructed unit-artifact AST");
    assert!(!artifact_cached.cache_hit);
    let artifact_design = (*artifact_cached.design).clone();
    assert_eq!(artifact_design.name, first.design.name);
    assert_eq!(artifact_design.n_nets, first.design.n_nets);
    assert_eq!(
        artifact_design.hierarchy.len(),
        first.design.hierarchy.len()
    );
    assert_eq!(artifact_design.assigns.len(), first.design.assigns.len());
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("unit IR cache stats after composite miss"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 0,
            misses: 2,
            evictions: 0,
            entries: 2,
        }
    );
    let leaf_first = second_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("reuse child partial IR lowered by composite relink");
    assert!(leaf_first.cache_hit);
    assert_eq!(leaf_first.design.name, "persistent_child");
    assert_eq!(leaf_first.design.n_nets, 2);
    assert_eq!(leaf_first.design.assigns.len(), 1);
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("unit IR cache stats after leaf reuse"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 1,
            misses: 2,
            evictions: 0,
            entries: 2,
        }
    );
    let leaf_second = second_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("second leaf unit partial-IR lower");
    assert!(leaf_second.cache_hit);
    assert_eq!(leaf_second.design.name, leaf_first.design.name);
    assert_eq!(leaf_second.design.n_nets, leaf_first.design.n_nets);
    assert_eq!(
        leaf_second.design.assigns.len(),
        leaf_first.design.assigns.len()
    );
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("leaf unit IR cache stats after hit"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 2,
            misses: 2,
            evictions: 0,
            entries: 2,
        }
    );
    let cached_composite = second_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("composite relink reuses cached child partial IR");
    assert!(cached_composite.cache_hit);
    assert_eq!(cached_composite.design.name, artifact_design.name);
    assert_eq!(cached_composite.design.n_nets, artifact_design.n_nets);
    assert_eq!(
        cached_composite.design.hierarchy.len(),
        artifact_design.hierarchy.len()
    );
    assert_eq!(
        cached_composite.design.assigns.len(),
        artifact_design.assigns.len()
    );
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("unit IR cache stats after cached composite relink"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 3,
            misses: 2,
            evictions: 0,
            entries: 2,
        }
    );
    let third_frontend =
        discover_slang_for_tests().expect("rediscover pinned slang for persistent IR");
    let persisted_composite = third_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("load persistent composite IR in a new frontend");
    assert!(persisted_composite.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&persisted_composite.design)).unwrap(),
        serde_json::to_value(&artifact_design).unwrap()
    );
    let fifth_frontend =
        discover_slang_for_tests().expect("rediscover pinned slang for persistent leaf IR");
    let persisted_leaf = fifth_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("load persistent leaf IR in a new frontend");
    assert!(persisted_leaf.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&persisted_leaf.design)).unwrap(),
        serde_json::to_value(Arc::as_ref(&leaf_first.design)).unwrap()
    );

    let leaf_ir_directory = cache.join("ir");
    let leaf_ir_path = std::fs::read_dir(&leaf_ir_directory)
        .expect("persistent leaf IR directory exists")
        .map(|entry| entry.expect("read persistent leaf IR path").path())
        .find(|path| {
            path.extension()
                .is_some_and(|extension| extension == "json")
        })
        .expect("persistent leaf IR artifact exists");
    std::fs::write(&leaf_ir_path, r#"{"schema":1}"#).expect("corrupt persistent leaf IR");
    let sixth_frontend =
        discover_slang_for_tests().expect("rediscover pinned slang after leaf IR corruption");
    let recovered_leaf = sixth_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("recover from corrupt persistent leaf IR");
    assert!(!recovered_leaf.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&recovered_leaf.design)).unwrap(),
        serde_json::to_value(Arc::as_ref(&leaf_first.design)).unwrap()
    );
    let repaired_persistent_leaf = sixth_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("load repaired persistent leaf IR");
    assert!(repaired_persistent_leaf.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&repaired_persistent_leaf.design)).unwrap(),
        serde_json::to_value(Arc::as_ref(&leaf_first.design)).unwrap()
    );

    std::fs::write(cache.join("composite-ir.json"), r#"{"schema":1}"#)
        .expect("corrupt persistent composite IR");
    let fourth_frontend =
        discover_slang_for_tests().expect("rediscover pinned slang after IR corruption");
    let recovered_composite = fourth_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("recover from corrupt persistent composite IR");
    assert!(!recovered_composite.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&recovered_composite.design)).unwrap(),
        serde_json::to_value(&artifact_design).unwrap()
    );
    let repaired_persistent_composite = fourth_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("load repaired persistent composite IR");
    assert!(repaired_persistent_composite.cache_hit);
    assert_eq!(
        serde_json::to_value(Arc::as_ref(&repaired_persistent_composite.design)).unwrap(),
        serde_json::to_value(&artifact_design).unwrap()
    );
    let composite_error = second_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_top")
        .expect_err("composite leaf partial-IR lower must fail closed");
    assert!(
        composite_error.contains("partial IR merge is not implemented"),
        "{composite_error}"
    );

    std::fs::write(child_artifact, r#"{"schema":1}"#).expect("corrupt persistent unit artifact");
    let corrupt_artifact_error = second_frontend
        .compile_project_unit_artifacts(&cache)
        .expect_err("corrupt unit artifacts must not lower");
    assert!(
        corrupt_artifact_error.contains("unit artifact cache is invalid"),
        "{corrupt_artifact_error}"
    );
    let unit_recovered = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("recover from corrupted persistent unit artifact");
    assert!(!unit_recovered.cache_hit);
    assert_eq!(unit_recovered.rebuilt_units, vec!["persistent_child"]);
    let unit_repaired = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("compile after persistent unit artifact repair");
    assert!(unit_repaired.cache_hit);

    std::fs::write(
        library.join("persistent_child.sv"),
        r#"
module persistent_child(input logic a, output logic y);
assign y = !a;
endmodule
"#,
    )
    .expect("change selected persistent dependency");
    let stale_error = second_frontend
        .compile_project_unit_artifacts(&cache)
        .expect_err("stale unit artifacts must not lower");
    assert!(
        stale_error.contains("stale for current project inputs"),
        "{stale_error}"
    );
    let stale_leaf_error = second_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect_err("stale leaf partial IR must not lower");
    assert!(
        stale_leaf_error.contains("stale for current project inputs"),
        "{stale_leaf_error}"
    );
    let changed = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("compile persistent project after dependency changed");
    assert!(!changed.cache_hit);
    assert_eq!(changed.rebuilt_units, vec!["persistent_child"]);
    let changed_leaf = second_frontend
        .compile_leaf_unit_artifact(&cache, "persistent_child")
        .expect("lower rebuilt child partial IR");
    assert!(!changed_leaf.cache_hit);
    assert_eq!(changed_leaf.design.name, "persistent_child");
    let changed_composite = second_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("lower rebuilt composite after child change");
    assert!(!changed_composite.cache_hit);
    assert_eq!(changed_composite.design.name, first.design.name);
    assert_eq!(
        changed_composite.design.hierarchy.len(),
        first.design.hierarchy.len()
    );

    std::fs::write(cache.join("ast.json"), "{corrupted").expect("corrupt AST cache");
    let recovered = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("recover from corrupted persistent AST");
    assert!(!recovered.cache_hit);
    assert!(recovered.rebuilt_units.is_empty());
    let repaired = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("compile after persistent cache repair");
    assert!(repaired.cache_hit);

    std::fs::write(
        library.join("new_persistent_candidate.sv"),
        r#"
module new_persistent_candidate();
endmodule
"#,
    )
    .expect("add persistent library candidate");
    let inventory_changed = second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("compile after persistent library inventory changed");
    assert!(!inventory_changed.cache_hit);
    assert!(inventory_changed.rebuilt_units.is_empty());
}

#[test]
fn slang_project_cache_persists_all_leaf_ir_despite_lru_eviction() {
    let Some(initial_frontend) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("persistent-all-leaf-ir");
    let cache = root.join("cache");
    let top_path = root.join("many_leaf_top.sv");
    let mut sources = vec![top_path.to_string_lossy().into_owned()];
    let mut instances = String::new();
    for index in 0..5 {
        let path = root.join(format!("many_leaf_child_{index}.sv"));
        std::fs::write(
            &path,
            format!(
                "module many_leaf_child_{index}(input logic a, output logic y);\n\
                 assign y = !a;\n\
                 endmodule\n"
            ),
        )
        .expect("write leaf child");
        sources.push(path.to_string_lossy().into_owned());
        instances.push_str(&format!(
            "many_leaf_child_{index} child_{index}(.a(a[{index}]), .y(y[{index}]));\n"
        ));
    }
    std::fs::write(
        &top_path,
        format!(
            "module many_leaf_top(input logic [4:0] a, output logic [4:0] y);\n{instances}endmodule\n"
        ),
    )
    .expect("write leaf-bearing top");
    let source_json = sources
        .iter()
        .map(|source| format!("\"{}\"", source.replace('\\', "\\\\")))
        .collect::<Vec<_>>()
        .join(",");
    let manifest_path = root.join("project.json");
    std::fs::write(
        &manifest_path,
        format!("{{\"top\":\"many_leaf_top\",\"sources\":[{source_json}]}}\n"),
    )
    .expect("write leaf project manifest");

    initial_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("build persistent project artifacts");
    let lowered = initial_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("lower leaf-bearing composite");
    assert!(!lowered.cache_hit);
    let leaf_artifact_count = std::fs::read_dir(cache.join("ir"))
        .expect("persistent leaf IR directory exists")
        .filter(|entry| {
            entry
                .as_ref()
                .expect("read persistent leaf IR entry")
                .path()
                .extension()
                .is_some_and(|extension| extension == "json")
        })
        .count();
    assert_eq!(leaf_artifact_count, 5);

    let second_frontend =
        discover_slang_for_tests().expect("rediscover pinned slang for every leaf fragment");
    for index in 0..5 {
        let leaf = second_frontend
            .compile_leaf_unit_artifact(&cache, &format!("many_leaf_child_{index}"))
            .unwrap_or_else(|error| panic!("load leaf {index}: {error}"));
        assert!(leaf.cache_hit, "leaf {index} must survive LRU eviction");
        assert_eq!(leaf.design.name, format!("many_leaf_child_{index}"));
    }
}

#[test]
fn slang_dirty_top_reuses_persistent_composite_child_fragment() {
    let Some(initial_frontend) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("persistent-composite-fragment");
    let cache = root.join("cache");
    let leaf_path = root.join("fragment_leaf.sv");
    let middle_path = root.join("fragment_middle.sv");
    let top_path = root.join("fragment_top.sv");
    std::fs::write(
        &leaf_path,
        r#"
module fragment_leaf(input logic a, output logic y);
assign y = !a;
endmodule
"#,
    )
    .expect("write fragment leaf");
    std::fs::write(
        &middle_path,
        r#"
module fragment_middle(input logic a, output logic y);
fragment_leaf child(.a(a), .y(y));
endmodule
"#,
    )
    .expect("write fragment middle");
    let original_top = r#"
module fragment_top(input logic a, output logic y);
fragment_middle middle(.a(a), .y(y));
endmodule
"#;
    std::fs::write(&top_path, original_top).expect("write fragment top");
    let sources = [top_path.clone(), middle_path, leaf_path.clone()];
    let manifest_path = root.join("project.json");
    std::fs::write(
        &manifest_path,
        serde_json::json!({
            "top": "fragment_top",
            "sources": sources,
        })
        .to_string(),
    )
    .expect("write fragment project manifest");

    initial_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("build fragment project artifacts");
    let first = initial_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("lower initial fragment hierarchy");
    assert!(!first.cache_hit);
    let fragment_count = std::fs::read_dir(cache.join("ir"))
        .expect("persistent fragment directory exists")
        .filter(|entry| {
            entry
                .as_ref()
                .expect("read persistent fragment entry")
                .path()
                .extension()
                .is_some_and(|extension| extension == "json")
        })
        .count();
    assert_eq!(fragment_count, 2, "leaf and middle fragments must persist");

    std::fs::remove_file(cache.join("composite-ir.json"))
        .expect("force fragment relink by removing whole-composite IR");
    let second_frontend =
        discover_slang_for_tests().expect("rediscover slang for clean fragment relink");
    let clean_relink = second_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("relink using persistent middle fragment");
    assert!(!clean_relink.cache_hit);
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("fragment stats"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 1,
            misses: 1,
            evictions: 0,
            entries: 3,
        }
    );

    std::fs::write(
        &top_path,
        r#"
module fragment_top(input logic a, output logic y);
wire changed_top_wire;
assign changed_top_wire = a;
fragment_middle middle(.a(a), .y(y));
endmodule
"#,
    )
    .expect("dirty only the top source");
    second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("rebuild dirty top artifacts");
    let third_frontend =
        discover_slang_for_tests().expect("rediscover slang after dirty top rebuild");
    let dirty_top = third_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("relink dirty top around unchanged middle");
    assert!(!dirty_top.cache_hit);
    assert!(dirty_top.design.n_nets > first.design.n_nets);
    assert_eq!(
        third_frontend.unit_ir_cache_stats().expect("dirty stats"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 1,
            misses: 1,
            evictions: 0,
            entries: 3,
        }
    );
}

#[test]
fn slang_dirty_top_reuses_generated_instance_array_composite_fragment() {
    let Some(initial_frontend) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("persistent-generated-composite-fragment");
    let cache = root.join("cache");
    let leaf_path = root.join("generated_fragment_leaf.sv");
    let middle_path = root.join("generated_fragment_middle.sv");
    let top_path = root.join("generated_fragment_top.sv");
    std::fs::write(
        &leaf_path,
        r#"
module generated_fragment_leaf(input logic a, output logic y);
assign y = !a;
endmodule
"#,
    )
    .expect("write generated fragment leaf");
    std::fs::write(
        &middle_path,
        r#"
module generated_fragment_middle(input logic [3:0] a, output logic [3:0] y);
generate
  if (1) begin : generated_scope
    generated_fragment_leaf cells[4] (.a(a), .y(y));
  end
endgenerate
endmodule
"#,
    )
    .expect("write generated fragment middle");
    std::fs::write(
        &top_path,
        r#"
module generated_fragment_top(input logic [3:0] a, output logic [3:0] y);
generated_fragment_middle middle(.a(a), .y(y));
endmodule
"#,
    )
    .expect("write generated fragment top");
    let sources = [top_path.clone(), middle_path, leaf_path.clone()];
    let manifest_path = root.join("project.json");
    std::fs::write(
        &manifest_path,
        serde_json::json!({
            "top": "generated_fragment_top",
            "sources": sources,
        })
        .to_string(),
    )
    .expect("write generated fragment manifest");

    initial_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("build generated fragment artifacts");
    let first = initial_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("lower generated fragment hierarchy");
    assert_eq!(first.design.hierarchy.len(), 6);
    let fragment_count = std::fs::read_dir(cache.join("ir"))
        .expect("generated fragment directory exists")
        .filter(|entry| {
            entry
                .as_ref()
                .expect("read generated fragment entry")
                .path()
                .extension()
                .is_some_and(|extension| extension == "json")
        })
        .count();
    assert_eq!(fragment_count, 2);

    std::fs::remove_file(cache.join("composite-ir.json")).expect("force generated fragment relink");
    let second_frontend =
        discover_slang_for_tests().expect("rediscover slang for generated fragment relink");
    let clean_relink = second_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("relink using generated middle fragment");
    assert!(!clean_relink.cache_hit);
    assert_eq!(
        second_frontend
            .unit_ir_cache_stats()
            .expect("generated clean stats"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 1,
            misses: 1,
            evictions: 0,
            entries: 3,
        }
    );

    std::fs::write(
        &top_path,
        r#"
module generated_fragment_top(input logic [3:0] a, output logic [3:0] y);
wire [3:0] changed_top_wire;
assign changed_top_wire = ~a;
generated_fragment_middle middle(.a(a), .y(y));
endmodule
"#,
    )
    .expect("dirty only generated fragment top");
    second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("rebuild dirty generated top artifacts");
    let third_frontend =
        discover_slang_for_tests().expect("rediscover slang after dirty generated top");
    let dirty_top = third_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("relink dirty generated top");
    assert!(!dirty_top.cache_hit);
    assert_eq!(dirty_top.design.hierarchy.len(), 6);
    assert!(dirty_top.design.n_nets > first.design.n_nets);
    assert_eq!(
        third_frontend
            .unit_ir_cache_stats()
            .expect("generated dirty stats"),
        eda_slang::SlangUnitIrCacheStats {
            hits: 1,
            misses: 1,
            evictions: 0,
            entries: 3,
        }
    );

    std::fs::write(
        &leaf_path,
        r#"
module generated_fragment_leaf(input logic a, output logic y);
assign y = a;
endmodule
"#,
    )
    .expect("dirty only generated fragment leaf");
    second_frontend
        .compile_project_manifest_with_cache(&manifest_path, Some(&cache))
        .expect("rebuild artifacts after leaf semantic change");
    let fourth_frontend = discover_slang_for_tests().expect("rediscover slang after dirty leaf");
    let dirty_leaf = fourth_frontend
        .compile_project_unit_artifacts_cached(&cache)
        .expect("relink transitive closure after dirty leaf");
    assert!(!dirty_leaf.cache_hit);
    assert_eq!(dirty_leaf.design.hierarchy.len(), 6);
    assert_eq!(
        fourth_frontend
            .unit_ir_cache_stats()
            .expect("generated dirty-leaf stats"),
        eda_slang::SlangUnitIrCacheStats {
            // The changed leaf has no old artifact under its new semantic key.
            // Middle relink lowers one generated element to create it; the other
            // three generated elements reuse that new fragment.
            hits: 3,
            misses: 3,
            evictions: 0,
            entries: 3,
        }
    );
    let mut simulator = eda_sim::Simulator::new(&dirty_leaf.design)
        .expect("create non-stale generated fragment simulator");
    simulator
        .set_input("a", &eda_core::logic::LogicWord::from_u64(4, 0b1001))
        .expect("set generated fragment input");
    simulator
        .run_until(0)
        .expect("settle generated fragment outputs");
    assert_eq!(
        simulator.read("y").unwrap().to_u64(),
        Some(0b1001),
        "old middle fragment must not hide the leaf semantic change"
    );
}

#[test]
fn slang_shared_project_database_plans_partial_recompilation() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("shared-project-database");
    let cache_root = root.join("caches");
    let database_path = root.join("projects.json");
    let mut manifests = Vec::new();
    let mut selected_dependencies = Vec::new();
    for index in 0..2 {
        let project = root.join(format!("project{index}"));
        let library = project.join("lib");
        std::fs::create_dir_all(&library).expect("create shared-database project library");
        let child = library.join(format!("shared_child{index}.sv"));
        std::fs::write(
            &child,
            format!(
                r#"
module shared_child{index}(input logic a, output logic y);
assign y = a;
endmodule
"#
            ),
        )
        .expect("write shared-database child");
        let source = project.join(format!("shared_top{index}.sv"));
        std::fs::write(
            &source,
            format!(
                r#"
module shared_top{index}(input logic a, output logic y);
shared_child{index} child(.a(a), .y(y));
endmodule
"#
            ),
        )
        .expect("write shared-database top");
        let manifest = project.join("project.json");
        std::fs::write(
            &manifest,
            format!(
                r#"
{{
  "top": "shared_top{index}",
  "sources": ["shared_top{index}.sv"],
  "library_directories": ["lib"],
  "library_extensions": [".sv"]
}}
"#
            ),
        )
        .expect("write shared-database manifest");
        slang
            .compile_project_manifest_with_shared_cache(&manifest, &cache_root, &database_path)
            .expect("compile shared-database project");
        manifests.push(std::fs::canonicalize(&manifest).unwrap());
        selected_dependencies.push(std::fs::canonicalize(child).unwrap());
    }

    let database =
        SlangProjectDependencyDatabase::load(&database_path).expect("load shared project database");
    let clean = database.partial_recompilation_plan();
    assert_eq!(clean.clean_projects, manifests);
    assert!(clean.dirty_projects.is_empty());
    assert!(clean.dirty_compilation_units.is_empty());
    assert!(clean.changed_files.is_empty());
    assert!(clean.missing_files.is_empty());

    let reverse = database.reverse_dependencies();
    let first = reverse
        .iter()
        .find(|entry| entry.file == selected_dependencies[0])
        .expect("first project dependency index");
    assert_eq!(first.projects, vec![manifests[0].clone()]);

    std::fs::write(
        &selected_dependencies[0],
        r#"
module shared_child0(input logic a, output logic y);
assign y = !a;
endmodule
"#,
    )
    .expect("change one shared-database dependency");
    let dirty = database.partial_recompilation_plan();
    assert_eq!(dirty.dirty_projects, vec![manifests[0].clone()]);
    assert_eq!(dirty.clean_projects, vec![manifests[1].clone()]);
    assert_eq!(dirty.changed_files, vec![selected_dependencies[0].clone()]);
    assert_eq!(
        dirty.dirty_compilation_units,
        vec![
            SlangCompilationUnit {
                project_manifest: manifests[0].clone(),
                name: "shared_child0".into(),
                kind: "Module".into(),
                source_path: selected_dependencies[0].clone(),
            },
            SlangCompilationUnit {
                project_manifest: manifests[0].clone(),
                name: "shared_top0".into(),
                kind: "Module".into(),
                source_path: manifests[0]
                    .parent()
                    .unwrap()
                    .join("shared_top0.sv")
                    .canonicalize()
                    .unwrap(),
            },
        ]
    );

    slang
        .compile_project_manifest_with_shared_cache(&manifests[0], &cache_root, &database_path)
        .expect("recompile dirty project and refresh database");
    let repaired = SlangProjectDependencyDatabase::load(&database_path)
        .expect("reload repaired shared database")
        .partial_recompilation_plan();
    assert!(repaired.dirty_projects.is_empty());
    assert!(repaired.dirty_compilation_units.is_empty());
    assert_eq!(repaired.clean_projects.len(), 2);
}

#[test]
fn slang_ast_lowering_enforces_the_schema_contract() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("ast-schema-contract");
    let source_path = root.join("schema_contract.sv");
    std::fs::write(
        &source_path,
        r#"
module schema_contract(output logic y);
assign y = 1'b1;
endmodule
"#,
    )
    .expect("write schema-contract source");
    let valid = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("schema_contract"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize schema-contract AST");
    let valid =
        serde_json::from_str::<serde_json::Value>(&valid).expect("parse schema-contract AST");
    slang
        .lower_ast_json(&valid.to_string())
        .expect("valid pinned slang AST satisfies the schema contract");
    assert_eq!(
        eda_slang::SUPPORTED_SLANG_AST_SCHEMA,
        "slang-ast-json-v1:root+definitions+source-info"
    );

    let mut missing_definitions = valid.clone();
    missing_definitions
        .as_object_mut()
        .expect("AST document object")
        .remove("definitions");
    let error = slang
        .lower_ast_json(&missing_definitions.to_string())
        .expect_err("missing definitions must fail the schema contract");
    assert!(
        error.contains("unsupported slang AST schema")
            && error.contains("definitions are not an array"),
        "unexpected missing-definitions error: {error}"
    );

    let mut missing_body = valid;
    if let Some(members) = missing_body
        .get_mut("design")
        .and_then(|d| d.get_mut("members"))
        .and_then(serde_json::Value::as_array_mut)
    {
        if let Some(instance) = members
            .iter_mut()
            .find(|member| member.get("kind").and_then(|k| k.as_str()) == Some("Instance"))
        {
            instance
                .as_object_mut()
                .expect("root Instance object")
                .remove("body");
        }
    }
    let error = slang
        .lower_ast_json(&missing_body.to_string())
        .expect_err("missing root body must fail the schema contract");
    assert!(
        error.contains("unsupported slang AST schema")
            && error.contains("root Instance has no body"),
        "unexpected missing-body error: {error}"
    );
}

fn validate_official_uvm_root(root: &Path) -> Result<PathBuf, String> {
    let source = root.join("src").join("uvm.sv");
    if !source.is_file() {
        return Err(format!(
            "UVM_HOME is set to {}, but the official UVM source is missing {}. Clone Accellera-official/uvm-core tag 2020.3.1 before running the required UVM gate",
            root.display(),
            source.display()
        ));
    }

    let version_path = root.join("src").join("base").join("uvm_version.svh");
    let version = std::fs::read_to_string(&version_path).map_err(|error| {
        format!(
            "cannot read official UVM version marker {}: {error}",
            version_path.display()
        )
    })?;
    if !version.contains("Accellera:1800.2:UVM:2020.3.1") {
        return Err(format!(
            "UVM_HOME {} does not contain the required official UVM 2020.3.1 source",
            root.display()
        ));
    }

    Ok(source)
}

fn official_uvm_sources() -> Option<(PathBuf, PathBuf)> {
    let Some(uvm_home) = std::env::var_os("UVM_HOME") else {
        if external_oracles_are_required() {
            panic!("EDA_REQUIRE_EXTERNAL_ORACLES is set, but UVM_HOME is not set");
        }
        return None;
    };
    let root = PathBuf::from(uvm_home);
    let source = validate_official_uvm_root(&root).expect("valid official UVM 2020.3.1 source");
    Some((root, source))
}

#[test]
fn official_uvm_validation_fails_closed_on_missing_source() {
    let root = temporary_directory("uvm-missing-source");
    let error = validate_official_uvm_root(&root)
        .expect_err("missing official UVM source must be an error, not a skip");
    assert!(error.contains("official UVM source is missing"), "{error}");
}

#[test]
fn official_uvm_validation_rejects_the_wrong_version() {
    let root = temporary_directory("uvm-wrong-version");
    let source_directory = root.join("src");
    let base_directory = source_directory.join("base");
    std::fs::create_dir_all(&base_directory).expect("create UVM source directories");
    std::fs::write(source_directory.join("uvm.sv"), "module uvm;\nendmodule\n")
        .expect("write UVM source stub");
    std::fs::write(
        base_directory.join("uvm_version.svh"),
        r#"parameter string UVM_VERSION_STRING = "Accellera:1800.2:UVM:2020.2.0";"#,
    )
    .expect("write wrong UVM version marker");

    let error = validate_official_uvm_root(&root)
        .expect_err("wrong official UVM version must be an error, not a skip");
    assert!(error.contains("required official UVM 2020.3.1"), "{error}");
}

#[test]
fn slang_compiles_macros_and_includes_through_the_direct_default_path() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("macros");
    let include_directory = root.join("include");
    std::fs::create_dir_all(&include_directory).expect("create include directory");
    std::fs::write(include_directory.join("width.svh"), "`define BUS_WIDTH 8\n")
        .expect("write include");
    let source = r#"
`include "width.svh"
`ifndef BUS_WIDTH
`define BUS_WIDTH 4
`endif
module top(input [`BUS_WIDTH-1:0] a, output [`BUS_WIDTH-1:0] y);
  assign y = ~a;
endmodule
"#;
    let source_path = root.join("top.sv");
    std::fs::write(&source_path, source).expect("write source");

    let options = PreprocessOptions {
        include_directories: vec![include_directory],
        ..Default::default()
    };
    let design = slang
        .compile_files(&[source_path], Some("top"), &options)
        .expect("slang frontend compiles preprocessed RTL");
    assert_eq!(design.name, "top");
    assert_eq!(design.n_nets, 16);

    let mut simulator = Simulator::new(&design).expect("create simulator");
    simulator
        .set_input("a", &LogicWord::from_u64(8, 0xa5))
        .expect("set input");
    assert_eq!(simulator.read("y").unwrap().to_u64(), Some(0x5a));
}

