#[test]
fn slang_ast_direct_lowering_compiles_and_simulates_simple_modules() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast");
    let source_path = root.join("simple.sv");
    std::fs::write(
        &source_path,
        r#"
module simple #(parameter SHIFT = 1)(
  input logic [3:0] a,
  input logic [3:0] b,
  output logic [3:0] sum,
  output logic [3:0] mask,
  output logic [3:0] shifted,
  output logic [3:0] inverted,
  output logic selected,
  output logic [7:0] concatenated,
  output logic [2:0] sliced,
  output logic [7:0] literal
);
  logic [3:0] initialized = 4'h3;
  assign sum = a + b;
  assign mask = a & b;
  assign shifted = a << SHIFT;
  assign inverted = ~a;
  assign selected = a[0] ? b[0] : a[1];
  assign concatenated = {a, b};
  assign sliced = a[3:1];
  assign literal = 8'hA5;
endmodule
"#,
    )
    .expect("write direct-lowering source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("simple"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower slang AST");
    let preprocessed_reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("simple"),
            &PreprocessOptions::default(),
        )
        .expect("lower the same module through the preprocessed path");
    assert_eq!(design.name, "simple");
    assert_eq!(design.n_nets, 48);
    assert_eq!(design.assigns.len(), 9);
    assert_eq!(preprocessed_reference.name, design.name);
    assert_eq!(preprocessed_reference.n_nets, design.n_nets);
    assert_eq!(preprocessed_reference.assigns.len(), design.assigns.len());
    assert_eq!(
        format!("{:?}", preprocessed_reference.ports),
        format!("{:?}", design.ports)
    );
    assert_eq!(
        format!("{:?}", preprocessed_reference.net_decls),
        format!("{:?}", design.net_decls)
    );

    let mut simulator = Simulator::new(&design).expect("create direct-AST simulator");
    simulator
        .set_input("a", &LogicWord::from_u64(4, 0b1101))
        .expect("set a");
    simulator
        .set_input("b", &LogicWord::from_u64(4, 0b0101))
        .expect("set b");
    let output = |name: &str| {
        simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("{name} was unknown"))
    };
    assert_eq!(output("sum"), 0b0010);
    assert_eq!(output("mask"), 0b0101);
    assert_eq!(output("shifted"), 0b1010);
    assert_eq!(output("inverted"), 0b0010);
    assert_eq!(output("selected"), 1);
    assert_eq!(output("concatenated"), 0b11010101);
    assert_eq!(output("sliced"), 0b110);
    assert_eq!(output("literal"), 0xa5);
    assert_eq!(output("initialized"), 3);

    let unsupported_path = root.join("unsupported.sv");
    std::fs::write(
        &unsupported_path,
        "module unsupported(output logic y); initial $fopen(\"unsupported\", \"x\"); endmodule\n",
    )
    .expect("write unsupported source");
    let error = slang
        .compile_files_via_ast(
            std::slice::from_ref(&unsupported_path),
            Some("unsupported"),
            &PreprocessOptions::default(),
        )
        .expect_err("direct path must reject unsupported constructs");
    assert!(
        error.contains("direct slang-AST lowering does not support system call \"$fopen\""),
        "unexpected error: {error}"
    );
}

#[test]
fn slang_bounded_negative_array_runtime_indices_execute() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("bounded-negative-array");
    let source_path = root.join("negative_array.sv");
    std::fs::write(
        &source_path,
        r#"
module negative_array(
  input logic signed [3:0] selector,
  output [7:0] q
);
logic [7:0] memory [-4:3];
initial begin
  memory[-4] = 8'd10;
  memory[-3] = 8'd20;
  memory[-2] = 8'd30;
  memory[-1] = 8'd40;
  memory[0] = 8'd50;
  memory[1] = 8'd60;
  memory[2] = 8'd70;
  memory[3] = 8'd80;
end
assign q = memory[selector];
endmodule
"#,
    )
    .expect("write negative-array source");

    let design = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("negative_array"),
            &PreprocessOptions::default(),
        )
        .expect("lower a negative-base unpacked array through the bounded path");
    let mut simulator = Simulator::new(&design).expect("create negative-array simulator");
    for index in -4_i64..=3 {
        simulator
            .set_input("selector", &LogicWord::from_u64(4, index as u32 as u64))
            .expect("set signed array selector");
        simulator.run_until(0).expect("evaluate array selector");
        let expected = ((index + 5) * 10) as u64;
        assert_eq!(
            simulator.read("q").unwrap().to_u64(),
            Some(expected),
            "wrong memory value for index {index}"
        );
    }
}

#[test]
fn slang_ast_direct_lowering_supports_display_tasks() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-display");
    let source_path = root.join("display.sv");
    std::fs::write(
        &source_path,
        r#"
module displays(
  input logic [3:0] a,
  input logic [3:0] b,
  input logic [3:0] unknown
);
  initial begin
    #1;
    $display("a=%b b=%h text%%", a, b);
    $displayb(a);
    $displayh(a);
    $displayo(a);
    $display("octal=%o", b);
    $writeo(a);
    $displayo(unknown);
    $display("decimal=%d", a);
    $display(a, b);
    $write("plain");
  end
endmodule
"#,
    )
    .expect("write display source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("displays"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower display tasks");
    let bounded = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("displays"),
            &PreprocessOptions::default(),
        )
        .expect("lower display tasks through the bounded path");
    assert_eq!(
        serde_json::to_value(&design).unwrap(),
        serde_json::to_value(&bounded).unwrap(),
        "direct and bounded display families must lower identically"
    );
    let mut simulator = Simulator::new(&design).expect("create display simulator");
    simulator
        .set_input("a", &LogicWord::from_u64(4, 0b1011))
        .unwrap();
    simulator
        .set_input("b", &LogicWord::from_u64(4, 0b0010))
        .unwrap();
    simulator.set_input("unknown", &LogicWord::xes(4)).unwrap();
    simulator.run_until(1).expect("run display initial block");
    assert_eq!(
        simulator.take_displays(),
        vec![
            "a=1011 b=2 text%\n",
            "1011\n",
            "b\n",
            "13\n",
            "octal=2\n",
            "13",
            "xx\n",
            "decimal=11\n",
            "11 2\n",
            "plain",
        ]
    );
}

