#[test]
fn slang_ast_direct_lowering_preserves_mixed_predefined_integer_semantics() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-mixed-predefined-integers");
    let source_path = root.join("mixed_predefined_integers.sv");
    std::fs::write(
        &source_path,
        r#"
module mixed_predefined_integers(
  input logic condition,
  output logic signed_less_than_unsigned,
  output logic signed_greater_than_unsigned,
  output byte signed byte_from_long,
  output byte unsigned byte_unsigned_from_signed,
  output longint unsigned long_unsigned_from_byte_signed,
  output shortint unsigned short_unsigned_from_int_signed,
  output int signed int_signed_from_short_unsigned,
  output int signed signed_byte_sum_as_int,
  output int unsigned unsigned_byte_sum_as_int,
  output int signed arithmetic_shift_right,
  output int signed logical_shift_right,
  output int signed logical_shift_left,
  output int unsigned mixed_unsigned_division,
  output int unsigned mixed_unsigned_modulus,
  output int signed conditional_signed_narrow
);
  int signed signed_minus_one = -1;
  int unsigned unsigned_one = 1;
  longint signed signed_long_source = -12345;
  byte signed signed_byte_source = -1;
  byte signed signed_byte_sum_operand = -128;
  byte unsigned unsigned_byte_sum_operand = 128;
  shortint unsigned unsigned_half_pattern = 16'h8000;
  int signed shift_source = -8;
  int unsigned unsigned_divisor = 2;
  byte signed conditional_byte = -1;
  int signed conditional_int = 0;

  assign signed_less_than_unsigned = signed_minus_one < unsigned_one;
  assign signed_greater_than_unsigned = signed_minus_one > unsigned_one;
  assign byte_from_long = byte'(signed_long_source);
  assign byte_unsigned_from_signed = byte unsigned'(signed_byte_source);
  assign long_unsigned_from_byte_signed = longint unsigned'(signed_byte_source);
  assign short_unsigned_from_int_signed = shortint unsigned'(signed_minus_one);
  assign int_signed_from_short_unsigned = int'(unsigned_half_pattern);
  assign signed_byte_sum_as_int = signed_byte_sum_operand + signed_byte_sum_operand;
  assign unsigned_byte_sum_as_int = unsigned_byte_sum_operand + unsigned_byte_sum_operand;
  assign arithmetic_shift_right = shift_source >>> 1;
  assign logical_shift_right = shift_source >> 1;
  assign logical_shift_left = shift_source << 1;
  assign mixed_unsigned_division = signed_minus_one / unsigned_divisor;
  assign mixed_unsigned_modulus = signed_minus_one % unsigned_divisor;
  assign conditional_signed_narrow = condition ? conditional_byte : conditional_int;
endmodule
"#,
    )
    .expect("write mixed predefined-integer source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("mixed_predefined_integers"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower mixed predefined integers");
    let integer_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("mixed_predefined_integers"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize mixed predefined-integer AST");
    let integer_summary = slang
        .summarize_ast_json(&integer_json)
        .expect("summarize mixed predefined-integer AST");
    integer_summary
        .validate_against_design(&design)
        .expect("exact mixed predefined-integer fingerprints should match");

    let mut simulator = Simulator::new(&design).expect("create mixed-integer simulator");
    simulator
        .run_until(0)
        .expect("execute mixed predefined integers");
    assert_eq!(
        simulator
            .read("signed_less_than_unsigned")
            .unwrap()
            .to_u64(),
        Some(0),
        "mixed signed/unsigned comparison must use unsigned semantics"
    );
    assert_eq!(
        simulator
            .read("signed_greater_than_unsigned")
            .unwrap()
            .to_u64(),
        Some(1),
        "-1 compared with unsigned one must order as a large unsigned value"
    );
    assert_eq!(
        simulator.read("byte_from_long").unwrap().to_u64(),
        Some(u64::from(-12345_i64 as u8))
    );
    assert_eq!(
        simulator
            .read("byte_unsigned_from_signed")
            .unwrap()
            .to_u64(),
        Some(u8::MAX.into())
    );
    assert_eq!(
        simulator
            .read("long_unsigned_from_byte_signed")
            .unwrap()
            .to_u64(),
        Some(u64::MAX)
    );
    assert_eq!(
        simulator
            .read("short_unsigned_from_int_signed")
            .unwrap()
            .to_u64(),
        Some(u16::MAX.into())
    );
    assert_eq!(
        simulator
            .read("int_signed_from_short_unsigned")
            .unwrap()
            .to_u64(),
        Some(0x8000)
    );
    assert_eq!(
        simulator.read("signed_byte_sum_as_int").unwrap().to_u64(),
        Some(-256_i32 as u32 as u64),
        "assignment context must widen signed byte arithmetic before wrapping"
    );
    assert_eq!(
        simulator.read("unsigned_byte_sum_as_int").unwrap().to_u64(),
        Some(256),
        "assignment context must widen unsigned byte arithmetic before wrapping"
    );
    assert_eq!(
        simulator.read("arithmetic_shift_right").unwrap().to_u64(),
        Some(-4_i32 as u32 as u64)
    );
    assert_eq!(
        simulator.read("logical_shift_right").unwrap().to_u64(),
        Some(0x7fff_fffc)
    );
    assert_eq!(
        simulator.read("logical_shift_left").unwrap().to_u64(),
        Some(-16_i32 as u32 as u64)
    );
    assert_eq!(
        simulator.read("mixed_unsigned_division").unwrap().to_u64(),
        Some(0xffff_ffff / 2)
    );
    assert_eq!(
        simulator.read("mixed_unsigned_modulus").unwrap().to_u64(),
        Some(1)
    );
    let conditional_unknown = simulator
        .read("conditional_signed_narrow")
        .expect("conditional output is readable");
    assert!(
        conditional_unknown
            .bits
            .iter()
            .enumerate()
            .all(|(index, bit)| index < 8 || bit.is_unknown()),
        "unknown condition must sign-extend the signed byte arm before X merging"
    );
    simulator
        .set_input("condition", &LogicWord::from_u64(1, 1))
        .expect("select signed conditional byte arm");
    simulator
        .run_until(1)
        .expect("evaluate true conditional arm");
    assert_eq!(
        simulator
            .read("conditional_signed_narrow")
            .unwrap()
            .to_u64(),
        Some(-1_i32 as u32 as u64)
    );
    simulator
        .set_input("condition", &LogicWord::from_u64(1, 0))
        .expect("select signed conditional int arm");
    simulator
        .run_until(2)
        .expect("evaluate false conditional arm");
    assert_eq!(
        simulator
            .read("conditional_signed_narrow")
            .unwrap()
            .to_u64(),
        Some(0)
    );
}

#[test]
fn slang_ast_direct_lowering_supports_floating_struct_members() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-struct");
    let source_path = root.join("floating_struct.sv");
    std::fs::write(
        &source_path,
        r#"
module floating_struct(
  output real a_out,
  output shortreal b_out,
  output logic [7:0] c_out,
  output real sum,
  output shortreal compact_sum
);
  typedef struct {
    real a;
    shortreal b;
    logic [7:0] c;
  } payload_t;
  payload_t p;

  initial begin
    p.a = 1.25;
    p.b = 0.5;
    p.c = 8'h5a;
    a_out = p.a;
    b_out = p.b;
    c_out = p.c;
    compact_sum = p.b + p.b;
  end
  always @(*) begin
    sum = p.a + p.a;
  end
endmodule
"#,
    )
    .expect("write floating-struct source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_struct"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating struct members");
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "p" && declaration.width == 104 }));

    let mut simulator = Simulator::new(&design).expect("create floating-struct simulator");
    simulator
        .run_until(0)
        .expect("execute floating struct members");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing floating-struct real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("floating-struct real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing floating-struct shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| panic!("floating-struct shortreal output {name} is unknown")),
        )
        .unwrap_or_else(|_| panic!("floating-struct shortreal output {name} exceeds 32 bits"));
        f32::from_bits(raw)
    }

    assert_eq!(real_output(&simulator, "a_out"), 1.25);
    assert_eq!(shortreal_output(&simulator, "b_out"), 0.5_f32);
    assert_eq!(simulator.read("c_out").unwrap().to_u64(), Some(0x5a));
    assert_eq!(real_output(&simulator, "sum"), 2.5);
    assert_eq!(shortreal_output(&simulator, "compact_sum"), 1.0_f32);
}

#[test]
fn slang_ast_direct_lowering_supports_nested_floating_struct_members() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-nested-floating-struct");
    let source_path = root.join("nested_floating_struct.sv");
    std::fs::write(
        &source_path,
        r#"
module nested_floating_struct(
  output real first_real,
  output shortreal first_shortreal,
  output logic [7:0] first_byte,
  output real copied_real,
  output shortreal copied_shortreal,
  output logic [7:0] copied_byte,
  output real scalar,
  output real nested_sum,
  output shortreal nested_compact_sum
);
  typedef struct {
    real x;
    shortreal y;
    logic [7:0] byte_value;
  } leaf_t;

  typedef struct {
    leaf_t first;
    leaf_t second;
    real scalar;
  } outer_t;

  outer_t value;

  initial begin
    value.first.x = 1.25;
    value.first.y = 0.5;
    value.first.byte_value = 8'h5a;
    value.second = value.first;
    value.scalar = 9.75;

    first_real = value.first.x;
    first_shortreal = value.first.y;
    first_byte = value.first.byte_value;
    copied_real = value.second.x;
    copied_shortreal = value.second.y;
    copied_byte = value.second.byte_value;
    scalar = value.scalar;
    nested_sum = value.first.x + value.second.x + value.scalar;
    nested_compact_sum = value.first.y + value.second.y;
  end
endmodule
"#,
    )
    .expect("write nested-floating-struct source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("nested_floating_struct"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower nested floating struct members");
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "value" && declaration.width == 272 }));

    let mut simulator = Simulator::new(&design).expect("create nested-floating-struct simulator");
    simulator
        .run_until(0)
        .expect("execute nested floating struct members");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing nested-floating real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("nested-floating real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing nested-floating shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| panic!("nested-floating shortreal output {name} is unknown")),
        )
        .unwrap_or_else(|_| panic!("nested-floating shortreal output {name} exceeds 32 bits"));
        f32::from_bits(raw)
    }

    assert_eq!(real_output(&simulator, "first_real"), 1.25);
    assert_eq!(shortreal_output(&simulator, "first_shortreal"), 0.5_f32);
    assert_eq!(simulator.read("first_byte").unwrap().to_u64(), Some(0x5a));
    assert_eq!(real_output(&simulator, "copied_real"), 1.25);
    assert_eq!(shortreal_output(&simulator, "copied_shortreal"), 0.5_f32);
    assert_eq!(simulator.read("copied_byte").unwrap().to_u64(), Some(0x5a));
    assert_eq!(real_output(&simulator, "scalar"), 9.75);
    assert_eq!(real_output(&simulator, "nested_sum"), 12.25);
    assert_eq!(shortreal_output(&simulator, "nested_compact_sum"), 1.0_f32);
}

#[test]
fn slang_ast_direct_lowering_supports_floating_struct_assignment_patterns() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-struct-pattern");
    let source_path = root.join("floating_struct_pattern.sv");
    std::fs::write(
        &source_path,
        r#"
module floating_struct_pattern(
  output real positional_real,
  output shortreal positional_shortreal,
  output logic [7:0] positional_byte,
  output real named_real,
  output shortreal named_shortreal,
  output logic [7:0] named_byte,
  output real real_sum,
  output shortreal shortreal_sum
);
  typedef struct {
    real a;
    shortreal b;
    logic [7:0] c;
  } payload_t;

  payload_t positional;
  payload_t named;

  initial begin
    positional = '{1.25, 0.5, 8'h5a};
    named = '{c: 8'ha5, b: 1.5, a: 3.75};

    positional_real = positional.a;
    positional_shortreal = positional.b;
    positional_byte = positional.c;
    named_real = named.a;
    named_shortreal = named.b;
    named_byte = named.c;
    real_sum = positional.a + named.a;
    shortreal_sum = positional.b + named.b;
  end
endmodule
"#,
    )
    .expect("write floating-struct-pattern source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_struct_pattern"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating struct assignment patterns");
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "positional" && declaration.width == 104 }));

    let pattern_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("floating_struct_pattern"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize floating-struct-pattern AST");
    let mut pattern_summary = slang
        .summarize_ast_json(&pattern_json)
        .expect("summarize floating-struct-pattern AST");
    pattern_summary
        .validate_against_design(&design)
        .expect("exact floating-struct-pattern fingerprints should match");
    if let Some(assignment) = pattern_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .target_names
                    .first()
                    .is_some_and(|name| name == "positional")
            })
        })
    {
        assignment.rhs.kind = "UnsupportedPattern".into();
    }
    let wrong_pattern_error = pattern_summary
        .validate_against_design(&design)
        .expect_err("wrong floating-struct pattern shape must fail");
    assert!(
        wrong_pattern_error.contains("positional") || wrong_pattern_error.contains("pattern"),
        "unexpected floating-struct-pattern error: {wrong_pattern_error}"
    );

    let mut simulator = Simulator::new(&design).expect("create floating-struct-pattern simulator");
    simulator
        .run_until(0)
        .expect("execute floating struct patterns");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing floating-pattern real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("floating-pattern real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing floating-pattern shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| panic!("floating-pattern shortreal output {name} is unknown")),
        )
        .unwrap_or_else(|_| panic!("floating-pattern shortreal output {name} exceeds 32 bits"));
        f32::from_bits(raw)
    }

    assert_eq!(real_output(&simulator, "positional_real"), 1.25);
    assert_eq!(
        shortreal_output(&simulator, "positional_shortreal"),
        0.5_f32
    );
    assert_eq!(
        simulator.read("positional_byte").unwrap().to_u64(),
        Some(0x5a)
    );
    assert_eq!(real_output(&simulator, "named_real"), 3.75);
    assert_eq!(shortreal_output(&simulator, "named_shortreal"), 1.5_f32);
    assert_eq!(simulator.read("named_byte").unwrap().to_u64(), Some(0xa5));
    assert_eq!(real_output(&simulator, "real_sum"), 5.0);
    assert_eq!(shortreal_output(&simulator, "shortreal_sum"), 2.0_f32);
}

#[test]
fn slang_ast_direct_lowering_supports_nested_floating_struct_assignment_patterns() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-nested-floating-struct-pattern");
    let source_path = root.join("nested_floating_struct_pattern.sv");
    std::fs::write(
        &source_path,
        r#"
module nested_floating_struct_pattern(
  output real positional_first_real,
  output shortreal positional_first_shortreal,
  output logic [7:0] positional_first_byte,
  output real positional_second_real,
  output shortreal positional_second_shortreal,
  output logic [7:0] positional_second_byte,
  output real positional_scalar,
  output real named_first_real,
  output shortreal named_first_shortreal,
  output logic [7:0] named_first_byte,
  output real named_second_real,
  output shortreal named_second_shortreal,
  output logic [7:0] named_second_byte,
  output real named_scalar,
  output real all_real_sum,
  output shortreal all_shortreal_sum
);
  typedef struct {
    real x;
    shortreal y;
    logic [7:0] byte_value;
  } leaf_t;

  typedef struct {
    leaf_t first;
    leaf_t second;
    real scalar;
  } outer_t;

  outer_t positional;
  outer_t named;

  initial begin
    positional = '{
      '{1.25, 0.5, 8'h5a},
      '{3.75, 1.5, 8'ha5},
      9.75
    };
    named = '{
      scalar: 8.5,
      second: '{byte_value: 8'hc3, y: -0.25, x: -2.5},
      first:  '{x: 2.25, y: 0.75, byte_value: 8'h3c}
    };

    positional_first_real = positional.first.x;
    positional_first_shortreal = positional.first.y;
    positional_first_byte = positional.first.byte_value;
    positional_second_real = positional.second.x;
    positional_second_shortreal = positional.second.y;
    positional_second_byte = positional.second.byte_value;
    positional_scalar = positional.scalar;

    named_first_real = named.first.x;
    named_first_shortreal = named.first.y;
    named_first_byte = named.first.byte_value;
    named_second_real = named.second.x;
    named_second_shortreal = named.second.y;
    named_second_byte = named.second.byte_value;
    named_scalar = named.scalar;

    all_real_sum = positional.first.x
      + positional.second.x
      + positional.scalar
      + named.first.x
      + named.second.x
      + named.scalar;
    all_shortreal_sum = positional.first.y
      + positional.second.y
      + named.first.y
      + named.second.y;
  end
endmodule
"#,
    )
    .expect("write nested-floating-struct-pattern source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("nested_floating_struct_pattern"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower nested floating struct patterns");
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "positional" && declaration.width == 272 }));

    let nested_pattern_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("nested_floating_struct_pattern"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize nested-floating-struct-pattern AST");
    let nested_pattern_summary = slang
        .summarize_ast_json(&nested_pattern_json)
        .expect("summarize nested-floating-struct-pattern AST");
    nested_pattern_summary
        .validate_against_design(&design)
        .expect("exact nested-floating-struct-pattern fingerprints should match");

    let mut simulator = Simulator::new(&design).expect("create nested-pattern simulator");
    simulator
        .run_until(0)
        .expect("execute nested floating struct patterns");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing nested-pattern real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("nested-pattern real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing nested-pattern shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| panic!("nested-pattern shortreal output {name} is unknown")),
        )
        .unwrap_or_else(|_| panic!("nested-pattern shortreal output {name} exceeds 32 bits"));
        f32::from_bits(raw)
    }

    assert_eq!(real_output(&simulator, "positional_first_real"), 1.25);
    assert_eq!(
        shortreal_output(&simulator, "positional_first_shortreal"),
        0.5_f32
    );
    assert_eq!(
        simulator.read("positional_first_byte").unwrap().to_u64(),
        Some(0x5a)
    );
    assert_eq!(real_output(&simulator, "positional_second_real"), 3.75);
    assert_eq!(
        shortreal_output(&simulator, "positional_second_shortreal"),
        1.5_f32
    );
    assert_eq!(
        simulator.read("positional_second_byte").unwrap().to_u64(),
        Some(0xa5)
    );
    assert_eq!(real_output(&simulator, "positional_scalar"), 9.75);

    assert_eq!(real_output(&simulator, "named_first_real"), 2.25);
    assert_eq!(
        shortreal_output(&simulator, "named_first_shortreal"),
        0.75_f32
    );
    assert_eq!(
        simulator.read("named_first_byte").unwrap().to_u64(),
        Some(0x3c)
    );
    assert_eq!(real_output(&simulator, "named_second_real"), -2.5);
    assert_eq!(
        shortreal_output(&simulator, "named_second_shortreal"),
        -0.25_f32
    );
    assert_eq!(
        simulator.read("named_second_byte").unwrap().to_u64(),
        Some(0xc3)
    );
    assert_eq!(real_output(&simulator, "named_scalar"), 8.5);
    assert_eq!(
        real_output(&simulator, "all_real_sum"),
        1.25 + 3.75 + 9.75 + 2.25 - 2.5 + 8.5
    );
    assert_eq!(
        shortreal_output(&simulator, "all_shortreal_sum"),
        0.5 + 1.5 + 0.75 - 0.25
    );
}

#[test]
fn slang_ast_direct_lowering_supports_floating_unpacked_unions() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-unpacked-union");
    let source_path = root.join("floating_unpacked_union.sv");
    std::fs::write(
        &source_path,
        r#"
module floating_unpacked_union(
  output real real_roundtrip,
  output logic [63:0] real_raw,
  output shortreal compact_roundtrip,
  output logic [31:0] compact_raw
);
  typedef union {
    real real_value;
    logic [63:0] raw_value;
  } real_union_t;

  typedef union {
    shortreal compact_value;
    logic [31:0] compact_raw_value;
  } compact_union_t;

  real_union_t wide;
  compact_union_t compact;

  initial begin
    wide.real_value = 1.25;
    real_roundtrip = wide.real_value;
    real_raw = wide.raw_value;

    wide.raw_value = 64'hc004000000000000;
    real_roundtrip = wide.real_value;
    real_raw = wide.raw_value;

    compact.compact_value = 0.5;
    compact_roundtrip = compact.compact_value;
    compact_raw = compact.compact_raw_value;

    compact.compact_raw_value = 32'hbe800000;
    compact_roundtrip = compact.compact_value;
    compact_raw = compact.compact_raw_value;
  end
endmodule
"#,
    )
    .expect("write floating-unpacked-union source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_unpacked_union"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating unpacked unions");
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "wide" && declaration.width == 64 }));
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| { declaration.name == "compact" && declaration.width == 32 }));

    let union_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("floating_unpacked_union"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize floating-unpacked-union AST");
    let mut union_summary = slang
        .summarize_ast_json(&union_json)
        .expect("summarize floating-unpacked-union AST");
    union_summary
        .validate_against_design(&design)
        .expect("exact floating-unpacked-union fingerprints should match");
    if let Some(assignment) = union_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .target_names
                    .first()
                    .is_some_and(|name| name == "real_roundtrip")
            })
        })
    {
        assignment.rhs.member_path = vec!["raw_value".into()];
        assignment.rhs.member_range = Some((63, 0));
        assignment.rhs.type_width = Some(64);
        assignment.rhs.type_name = "logic [63:0]".into();
    }
    let wrong_union_member_error = union_summary
        .validate_against_design(&design)
        .expect_err("wrong floating-union member must fail");
    assert!(
        wrong_union_member_error.contains("Range:63:0")
            || wrong_union_member_error.contains("real_value")
            || wrong_union_member_error.contains("raw_value"),
        "unexpected floating-union fingerprint error: {wrong_union_member_error}"
    );

    let mut simulator = Simulator::new(&design).expect("create floating-union simulator");
    simulator
        .run_until(0)
        .expect("execute floating unpacked unions");

    let final_real_bits = simulator.read("real_raw").unwrap().to_u64().unwrap();
    assert_eq!(f64::from_bits(final_real_bits), -2.5);
    assert_eq!(final_real_bits, (-2.5_f64).to_bits());

    let final_compact_bits =
        u32::try_from(simulator.read("compact_raw").unwrap().to_u64().unwrap()).unwrap();
    assert_eq!(f32::from_bits(final_compact_bits), -0.25);
    assert_eq!(final_compact_bits, (-0.25_f32).to_bits());
}

#[test]
fn slang_ast_direct_lowering_supports_floating_struct_arrays() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-struct-array");
    let source_path = root.join("floating_struct_array.sv");
    std::fs::write(
        &source_path,
        r#"
module floating_struct_array(
  input int index,
  output real first_real,
  output shortreal first_shortreal,
  output logic [7:0] first_byte,
  output real selected_real,
  output shortreal selected_shortreal,
  output logic [7:0] selected_byte,
  output real real_sum,
  output shortreal shortreal_sum
);
  typedef struct {
    real a;
    shortreal b;
    logic [7:0] c;
  } payload_t;
  payload_t values[0:2];

  initial begin
    values[0].a = 1.25;
    values[0].b = 0.5;
    values[0].c = 8'h5a;
    values[1].a = 3.75;
    values[1].b = 1.5;
    values[1].c = 8'ha5;
    values[2].a = -2.5;
    values[2].b = -0.25;
    values[2].c = 8'h3c;
    first_real = values[0].a;
    first_shortreal = values[0].b;
    first_byte = values[0].c;
  end

  always @(*) begin
    selected_real = values[index].a;
    selected_shortreal = values[index].b;
    selected_byte = values[index].c;
    real_sum = values[index].a + values[index].a;
    shortreal_sum = values[index].b + values[index].b;
  end
endmodule
"#,
    )
    .expect("write floating-struct-array source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_struct_array"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating struct arrays");
    assert_eq!(design.memories.len(), 1);
    assert_eq!(design.memories[0].element_width, 104);

    let mut simulator = Simulator::new(&design).expect("create floating-struct-array simulator");
    simulator
        .run_until(0)
        .expect("execute floating struct elements");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing floating-struct-array real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("floating-struct-array real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing floating-struct-array shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| {
                    panic!("floating-struct-array shortreal output {name} is unknown")
                }),
        )
        .unwrap_or_else(|_| {
            panic!("floating-struct-array shortreal output {name} exceeds 32 bits")
        });
        f32::from_bits(raw)
    }

    assert_eq!(real_output(&simulator, "first_real"), 1.25);
    assert_eq!(shortreal_output(&simulator, "first_shortreal"), 0.5_f32);
    assert_eq!(simulator.read("first_byte").unwrap().to_u64(), Some(0x5a));

    for (index, real, compact, byte) in [
        (0_u64, 1.25_f64, 0.5_f32, 0x5a_u64),
        (1, 3.75, 1.5, 0xa5),
        (2, -2.5, -0.25, 0x3c),
    ] {
        simulator
            .set_input("index", &LogicWord::from_u64(32, index))
            .expect("set floating-struct-array index");
        simulator
            .run_until(0)
            .expect("select floating struct element");
        assert_eq!(
            real_output(&simulator, "selected_real"),
            real,
            "unexpected real member {index}"
        );
        assert_eq!(
            shortreal_output(&simulator, "selected_shortreal"),
            compact,
            "unexpected shortreal member {index}"
        );
        assert_eq!(
            simulator.read("selected_byte").unwrap().to_u64(),
            Some(byte),
            "unexpected byte member {index}"
        );
        assert_eq!(
            real_output(&simulator, "real_sum"),
            real + real,
            "unexpected real member sum {index}"
        );
        if compact.is_nan() {
            assert!(shortreal_output(&simulator, "shortreal_sum").is_nan());
        } else {
            assert_eq!(
                shortreal_output(&simulator, "shortreal_sum"),
                compact + compact,
                "unexpected shortreal member sum {index}"
            );
        }
    }
}

#[test]
fn slang_ast_direct_lowering_supports_dynamic_floating_struct_containers() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-dynamic-floating-struct-containers");
    let source_path = root.join("dynamic_floating_struct_containers.sv");
    std::fs::write(
        &source_path,
        r#"
module dynamic_floating_struct_containers(
  input int key,
  output int dynamic_size,
  output int queue_size,
  output int associative_count,
  output real dynamic_real,
  output shortreal dynamic_shortreal,
  output logic [7:0] dynamic_byte,
  output real queue_real,
  output shortreal queue_shortreal,
  output logic [7:0] queue_byte,
  output real associative_real,
  output shortreal associative_shortreal,
  output logic [7:0] associative_byte
);
  typedef struct {
    real a;
    shortreal b;
    logic [7:0] c;
  } payload_t;

  payload_t source;
  payload_t dynamic_values[];
  payload_t queue_values[$];
  payload_t associative_values[int];

  initial begin
    #1;
    source.a = 1.25;
    source.b = 0.5;
    source.c = 8'h5a;

    dynamic_values = new[2];
    dynamic_values[0] = source;
    dynamic_values[1].a = 3.75;
    dynamic_values[1].b = 1.5;
    dynamic_values[1].c = 8'ha5;
    dynamic_size = dynamic_values.size();
    dynamic_real = dynamic_values[1].a;
    dynamic_shortreal = dynamic_values[1].b;
    dynamic_byte = dynamic_values[1].c;

    queue_values.push_back(source);
    queue_values.push_front(source);
    queue_size = queue_values.size();
    queue_real = queue_values[1].a;
    queue_shortreal = queue_values[1].b;
    queue_byte = queue_values[1].c;

    associative_values[key] = source;
    associative_count = associative_values.num();
    associative_real = associative_values[key].a;
    associative_shortreal = associative_values[key].b;
    associative_byte = associative_values[key].c;
  end
endmodule
"#,
    )
    .expect("write dynamic-floating-struct-container source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("dynamic_floating_struct_containers"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower dynamic floating struct containers");
    assert_eq!(design.memories.len(), 3);
    assert!(design.memories.iter().all(|memory| memory.dynamic));
    assert!(design
        .memories
        .iter()
        .all(|memory| memory.element_width == 104));
    assert!(!design.memories[0].queue && !design.memories[0].associative);
    assert!(design.memories[1].queue && !design.memories[1].associative);
    assert!(!design.memories[2].queue && design.memories[2].associative);

    let mut simulator = Simulator::new(&design).expect("create dynamic-struct-container simulator");
    simulator
        .set_input("key", &LogicWord::from_u64(32, 41))
        .expect("set associative key");
    simulator
        .run_until(1)
        .expect("execute dynamic floating struct containers");

    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing dynamic-struct real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("dynamic-struct real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
        let raw = u32::try_from(
            simulator
                .read(name)
                .unwrap_or_else(|| panic!("missing dynamic-struct shortreal output {name}"))
                .to_u64()
                .unwrap_or_else(|| panic!("dynamic-struct shortreal output {name} is unknown")),
        )
        .unwrap_or_else(|_| panic!("dynamic-struct shortreal output {name} exceeds 32 bits"));
        f32::from_bits(raw)
    }

    assert_eq!(simulator.read("dynamic_size").unwrap().to_u64(), Some(2));
    assert_eq!(simulator.read("queue_size").unwrap().to_u64(), Some(2));
    assert_eq!(
        simulator.read("associative_count").unwrap().to_u64(),
        Some(1)
    );
    assert_eq!(real_output(&simulator, "dynamic_real"), 3.75);
    assert_eq!(shortreal_output(&simulator, "dynamic_shortreal"), 1.5_f32);
    assert_eq!(simulator.read("dynamic_byte").unwrap().to_u64(), Some(0xa5));
    assert_eq!(real_output(&simulator, "queue_real"), 1.25);
    assert_eq!(shortreal_output(&simulator, "queue_shortreal"), 0.5_f32);
    assert_eq!(simulator.read("queue_byte").unwrap().to_u64(), Some(0x5a));
    assert_eq!(real_output(&simulator, "associative_real"), 1.25);
    assert_eq!(
        shortreal_output(&simulator, "associative_shortreal"),
        0.5_f32
    );
    assert_eq!(
        simulator.read("associative_byte").unwrap().to_u64(),
        Some(0x5a)
    );
}

#[test]
fn slang_ast_direct_lowering_connects_floating_struct_ports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-struct-ports");
    let source_path = root.join("floating_struct_ports.sv");
    std::fs::write(
        &source_path,
        r#"
package payload_pkg;
  typedef struct {
    real a;
    shortreal b;
    logic [7:0] c;
  } payload_t;
endpackage

module payload_child(source, destination);
  import payload_pkg::*;
  input payload_t source;
  output payload_t destination;
  assign destination.a = source.a + 1.0;
  assign destination.b = source.b + 0.25;
  assign destination.c = source.c + 8'd1;
endmodule

module floating_struct_ports(
  source,
  destination,
  observed_real,
  observed_shortreal,
  observed_byte
);
  import payload_pkg::*;
  input payload_t source;
  output payload_t destination;
  output real observed_real;
  output shortreal observed_shortreal;
  output logic [7:0] observed_byte;
  payload_child child(
    .source(source),
    .destination(destination)
  );
  assign observed_real = destination.a;
  assign observed_shortreal = destination.b;
  assign observed_byte = destination.c;
endmodule
"#,
    )
    .expect("write floating-struct-port source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_struct_ports"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating struct ports");
    assert_eq!(design.ports.len(), 5);
    assert_eq!(design.hierarchy.len(), 2);

    fn payload_word(real: f64, compact: f32, byte: u8) -> LogicWord {
        let mut bits = LogicWord::from_u64(64, real.to_bits()).bits;
        bits.extend(LogicWord::from_u64(32, u64::from(compact.to_bits())).bits);
        bits.extend(LogicWord::from_u64(8, u64::from(byte)).bits);
        LogicWord { bits }
    }

    let mut simulator = Simulator::new(&design).expect("create floating-struct-port simulator");
    simulator
        .set_input("source", &payload_word(10.25, 1.5, 0x5a))
        .expect("set floating struct input port");
    simulator
        .run_until(0)
        .expect("evaluate floating struct ports");

    let destination = simulator
        .read("destination")
        .expect("read struct output port");
    let destination_real = f64::from_bits(destination.slice(63, 0).to_u64().unwrap());
    let destination_compact =
        f32::from_bits(u32::try_from(destination.slice(95, 64).to_u64().unwrap()).unwrap());
    let destination_byte = u8::try_from(destination.slice(103, 96).to_u64().unwrap()).unwrap();
    assert_eq!(destination_real, 11.25);
    assert_eq!(destination_compact, 1.75_f32);
    assert_eq!(destination_byte, 0x5b);

    let observed_real = f64::from_bits(simulator.read("observed_real").unwrap().to_u64().unwrap());
    let observed_compact = f32::from_bits(
        u32::try_from(
            simulator
                .read("observed_shortreal")
                .unwrap()
                .to_u64()
                .unwrap(),
        )
        .unwrap(),
    );
    let observed_byte =
        u8::try_from(simulator.read("observed_byte").unwrap().to_u64().unwrap()).unwrap();
    assert_eq!(observed_real, 11.25);
    assert_eq!(observed_compact, 1.75_f32);
    assert_eq!(observed_byte, 0x5b);
}

#[test]
fn slang_ast_direct_lowering_supports_floating_array_ports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-floating-array-ports");
    let source_path = root.join("floating_array_ports.sv");
    std::fs::write(
        &source_path,
        r#"
module floating_array_ports(
  input real source[0:1],
  input shortreal compact_source[0:1],
  output real destination[0:1],
  output shortreal compact_destination[0:1],
  output real observed,
  output shortreal compact_observed
);
  initial begin
    destination[0] = 10.25;
    destination[1] = 11.5;
    compact_destination[0] = 0.25;
    compact_destination[1] = 1.5;
  end
  assign observed = source[1];
  assign compact_observed = compact_source[0];
endmodule
"#,
    )
    .expect("write floating-array-port source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("floating_array_ports"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower floating array ports");
    assert_eq!(design.array_ports.len(), 4);

    let mut simulator = Simulator::new(&design).expect("create floating-array-port simulator");
    simulator.run_until(0).expect("settle array initializers");
    simulator
        .set_ordinary_array_input("source", &[1], &LogicWord::from_u64(64, 12.5_f64.to_bits()))
        .expect("set real array input");
    simulator
        .set_ordinary_array_input(
            "compact_source",
            &[0],
            &LogicWord::from_u64(32, u64::from(2.5_f32.to_bits())),
        )
        .expect("set shortreal array input");
    simulator
        .run_until(0)
        .expect("observe floating array inputs");

    let observed_bits = simulator.read("observed").unwrap().to_u64().unwrap();
    assert_eq!(f64::from_bits(observed_bits), 12.5);
    let compact_bits = u32::try_from(
        simulator
            .read("compact_observed")
            .unwrap()
            .to_u64()
            .unwrap(),
    )
    .unwrap();
    assert_eq!(f32::from_bits(compact_bits), 2.5);

    let real_output = simulator
        .read_ordinary_array_output("destination", &[1])
        .expect("read real array output");
    assert_eq!(f64::from_bits(real_output.to_u64().unwrap()), 11.5);
    let shortreal_output = simulator
        .read_ordinary_array_output("compact_destination", &[0])
        .expect("read shortreal array output");
    assert_eq!(
        f32::from_bits(u32::try_from(shortreal_output.to_u64().unwrap()).unwrap()),
        0.25
    );
}

#[test]
fn slang_ast_direct_lowering_connects_child_floating_array_ports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-child-floating-array-ports");
    let source_path = root.join("child_floating_array_ports.sv");
    std::fs::write(
        &source_path,
        r#"
module real_leaf(
  input real source[0:1],
  output real destination[0:1]
);
  assign destination[0] = source[0] + 1.0;
  assign destination[1] = source[1] * 2.0;
endmodule

module shortreal_leaf(
  input shortreal source[0:1],
  output shortreal destination[0:1]
);
  assign destination[0] = source[0] + 0.25;
  assign destination[1] = source[1] * 2.0;
endmodule

module child_floating_array_ports(
  input real real_source[0:1],
  output real real_destination[0:1],
  input shortreal compact_source[0:1],
  output shortreal compact_destination[0:1]
);
  real_leaf real_instance(
    .source(real_source),
    .destination(real_destination)
  );
  shortreal_leaf compact_instance(
    .source(compact_source),
    .destination(compact_destination)
  );
endmodule
"#,
    )
    .expect("write child floating-array-port source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("child_floating_array_ports"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower child floating array ports");
    assert_eq!(design.array_ports.len(), 0);
    assert_eq!(design.memory_ports.len(), 4);
    assert_eq!(design.array_connections.len(), 0);
    assert_eq!(design.memory_connections.len(), 4);

    let mut simulator = Simulator::new(&design).expect("create child floating-port simulator");
    simulator.run_until(0).expect("settle child connections");
    simulator
        .set_memory_input(
            "real_source",
            &[0],
            &LogicWord::from_u64(64, 10.5_f64.to_bits()),
        )
        .expect("set child real input element zero");
    simulator
        .set_memory_input(
            "real_source",
            &[1],
            &LogicWord::from_u64(64, 12.5_f64.to_bits()),
        )
        .expect("set child real input element one");
    simulator
        .set_memory_input(
            "compact_source",
            &[0],
            &LogicWord::from_u64(32, u64::from(1.5_f32.to_bits())),
        )
        .expect("set child shortreal input element zero");
    simulator
        .set_memory_input(
            "compact_source",
            &[1],
            &LogicWord::from_u64(32, u64::from(2.5_f32.to_bits())),
        )
        .expect("set child shortreal input element one");
    simulator
        .run_until(0)
        .expect("evaluate child floating ports");

    let real_zero = simulator
        .read_memory_output("real_destination", &[0])
        .expect("read child real output zero");
    assert_eq!(
        f64::from_bits(real_zero.to_u64().expect("known real output")),
        11.5
    );
    let real_one = simulator
        .read_memory_output("real_destination", &[1])
        .expect("read child real output one");
    assert_eq!(
        f64::from_bits(real_one.to_u64().expect("known real output")),
        25.0
    );
    let compact_zero = simulator
        .read_memory_output("compact_destination", &[0])
        .expect("read child shortreal output zero");
    assert_eq!(
        f32::from_bits(
            u32::try_from(compact_zero.to_u64().expect("known shortreal output")).unwrap()
        ),
        1.75_f32
    );
    let compact_one = simulator
        .read_memory_output("compact_destination", &[1])
        .expect("read child shortreal output one");
    assert_eq!(
        f32::from_bits(
            u32::try_from(compact_one.to_u64().expect("known shortreal output")).unwrap()
        ),
        5.0_f32
    );
}

#[test]
fn slang_ast_direct_lowering_rounds_fractional_delays_to_precision() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-fractional-delay");
    let source_path = root.join("fractional_delay.sv");
    std::fs::write(
        &source_path,
        r#"
module fractional_delay_probe(
  input logic source,
  output real elapsed,
  output logic delayed
);
  timeunit 1ns;
  timeprecision 100ps;
  initial begin
    #1.55 elapsed = $realtime;
  end
  assign #1.54 delayed = source;
endmodule
"#,
    )
    .expect("write fractional-delay source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("fractional_delay_probe"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower fractional delays");
    assert_eq!(design.time_scale.precision_exponent, -10);

    let mut simulator = Simulator::new(&design).expect("create fractional-delay simulator");
    simulator
        .set_input("source", &LogicWord::ones(1))
        .expect("set delayed-assignment input");
    simulator
        .run_until(15)
        .expect("run through rounded continuous delay");
    assert!(
        simulator
            .read("delayed")
            .is_some_and(|value| value.to_u64() == Some(1)),
        "1.54ns continuous delay must round to 15 precision ticks"
    );
    assert!(
        simulator
            .read("elapsed")
            .is_some_and(|value| !value.is_fully_known()),
        "1.55ns procedural delay must not fire before rounding to 16 ticks"
    );

    simulator
        .run_until(16)
        .expect("run rounded procedural delay");
    let elapsed_bits = simulator.read("elapsed").expect("read elapsed realtime");
    let elapsed = f64::from_bits(elapsed_bits.to_u64().expect("known elapsed"));
    assert!(
        (elapsed - 1.6).abs() < f64::EPSILON,
        "unexpected fractional-delay elapsed time: {elapsed}"
    );

    let invalid_path = root.join("negative_fractional_delay.sv");
    std::fs::write(
        &invalid_path,
        r#"
module negative_fractional_delay(output logic value);
  timeunit 1ns;
  timeprecision 100ps;
  initial #(-1.5) value = 1;
endmodule
"#,
    )
    .expect("write negative fractional-delay source");
    let error = slang
        .compile_files_via_ast(
            std::slice::from_ref(&invalid_path),
            Some("negative_fractional_delay"),
            &PreprocessOptions::default(),
        )
        .expect_err("negative fractional delays must fail closed");
    assert!(
        error.contains("delay control must be a nonnegative finite real constant"),
        "unexpected negative fractional-delay error: {error}"
    );
}

#[test]
fn slang_ast_direct_lowering_uses_real_values_as_conditions() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-real-condition");
    let source_path = root.join("real_condition.sv");
    std::fs::write(
        &source_path,
        r#"
module real_condition(
  input real value,
  output logic zero,
  output logic nonzero,
  output logic negative
);
  always @(*) begin
    zero = value ? 1'b0 : 1'b1;
    nonzero = value ? 1'b1 : 1'b0;
    negative = (value < 0.0) ? 1'b1 : 1'b0;
  end
endmodule
"#,
    )
    .expect("write real-condition source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("real_condition"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower real conditions");
    let mut simulator = Simulator::new(&design).expect("create real-condition simulator");

    for (value, zero, nonzero, negative) in [
        (0.0_f64, 1_u64, 0, 0),
        (1.5_f64, 0, 1, 0),
        (-2.25_f64, 0, 1, 1),
    ] {
        simulator
            .set_input("value", &LogicWord::from_u64(64, value.to_bits()))
            .expect("set real condition input");
        simulator.run_until(0).expect("evaluate real condition");
        assert_eq!(
            simulator.read("zero").unwrap().to_u64(),
            Some(zero),
            "unexpected zero test for {value}"
        );
        assert_eq!(
            simulator.read("nonzero").unwrap().to_u64(),
            Some(nonzero),
            "unexpected nonzero test for {value}"
        );
        assert_eq!(
            simulator.read("negative").unwrap().to_u64(),
            Some(negative),
            "unexpected negative test for {value}"
        );
    }
}

#[test]
fn slang_ast_direct_lowering_preserves_real_nan_and_subnormal_semantics() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-real-nan-subnormal");
    let source_path = root.join("real_nan_subnormal.sv");
    std::fs::write(
        &source_path,
        r#"
module real_nan_subnormal(
  input real lhs,
  input real rhs,
  output real sum,
  output real negated,
  output real quotient,
  output logic lhs_condition,
  output logic lhs_self_equal,
  output logic lhs_less_self,
  output logic lhs_greater_self,
  output logic lhs_nonzero,
  output logic lhs_less_one,
  output logic lhs_negative
);
  always @(*) begin
    sum = lhs + 0.0;
    negated = -lhs;
    quotient = 1.0 / rhs;
    lhs_condition = lhs ? 1'b1 : 1'b0;
    lhs_self_equal = lhs == lhs;
    lhs_less_self = lhs < lhs;
    lhs_greater_self = lhs > lhs;
    lhs_nonzero = lhs != 0.0;
    lhs_less_one = lhs < 1.0;
    lhs_negative = lhs < 0.0;
  end
endmodule
"#,
    )
    .expect("write real NaN/subnormal source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("real_nan_subnormal"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower real NaN/subnormal semantics");
    let mut simulator = Simulator::new(&design).expect("create real NaN/subnormal simulator");

    fn set_real(simulator: &mut Simulator, name: &str, value: f64) -> Result<(), String> {
        simulator.set_input(name, &LogicWord::from_u64(64, value.to_bits()))
    }
    fn real_output(simulator: &Simulator, name: &str) -> f64 {
        let bits = simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing real output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("real output {name} is unknown"));
        f64::from_bits(bits)
    }
    fn logic_output(simulator: &Simulator, name: &str) -> u64 {
        simulator
            .read(name)
            .unwrap_or_else(|| panic!("missing logic output {name}"))
            .to_u64()
            .unwrap_or_else(|| panic!("logic output {name} is unknown"))
    }

    let vectors = [
        (
            f64::from_bits(0x7ff8_0000_0000_0000),
            2.0_f64,
            [1, 0, 0, 0, 1, 0, 0],
        ),
        (
            f64::from_bits(0x7ff0_0000_0000_0001),
            2.0_f64,
            [1, 0, 0, 0, 1, 0, 0],
        ),
        (f64::from_bits(1), 0.5_f64, [1, 1, 0, 0, 1, 1, 0]),
        (
            f64::from_bits(0x8000_0000_0000_0001),
            0.5_f64,
            [1, 1, 0, 0, 1, 1, 1],
        ),
        (f64::INFINITY, 2.0_f64, [1, 1, 0, 0, 1, 0, 0]),
    ];

    for (lhs, rhs, expected) in vectors {
        set_real(&mut simulator, "lhs", lhs).expect("set real lhs input");
        set_real(&mut simulator, "rhs", rhs).expect("set real rhs input");
        simulator
            .run_until(0)
            .expect("evaluate real edge semantics");

        let sum = real_output(&simulator, "sum");
        let negated = real_output(&simulator, "negated");
        let quotient = real_output(&simulator, "quotient");
        if lhs.is_nan() {
            assert!(sum.is_nan(), "NaN must propagate through addition");
            assert!(negated.is_nan(), "NaN must propagate through negation");
        } else {
            assert_eq!(sum, lhs, "unexpected addition result for {lhs}");
            assert_eq!(
                negated.to_bits(),
                (-lhs).to_bits(),
                "unexpected negation result for {lhs}"
            );
        }
        assert_eq!(quotient, 1.0 / rhs, "unexpected quotient for {rhs}");

        let names = [
            "lhs_condition",
            "lhs_self_equal",
            "lhs_less_self",
            "lhs_greater_self",
            "lhs_nonzero",
            "lhs_less_one",
            "lhs_negative",
        ];
        for (name, expected) in names.iter().zip(expected) {
            assert_eq!(
                logic_output(&simulator, name),
                expected as u64,
                "unexpected {name} for lhs={lhs:?}"
            );
        }
    }

    set_real(&mut simulator, "lhs", 1.0).expect("set finite division lhs");
    set_real(&mut simulator, "rhs", 0.0).expect("set positive-zero divisor");
    simulator.run_until(0).expect("evaluate positive infinity");
    assert_eq!(
        real_output(&simulator, "quotient"),
        f64::INFINITY,
        "1.0 / +0.0 must produce positive infinity"
    );

    set_real(&mut simulator, "rhs", f64::from_bits(0x8000_0000_0000_0000))
        .expect("set negative-zero divisor");
    simulator.run_until(0).expect("evaluate negative infinity");
    assert_eq!(
        real_output(&simulator, "quotient"),
        f64::NEG_INFINITY,
        "1.0 / -0.0 must produce negative infinity"
    );

    set_real(&mut simulator, "rhs", f64::from_bits(0x7ff8_0000_0000_0000))
        .expect("set NaN divisor");
    simulator.run_until(0).expect("evaluate NaN quotient");
    assert!(
        real_output(&simulator, "quotient").is_nan(),
        "1.0 / NaN must produce NaN"
    );
}

#[test]
fn slang_ast_direct_lowering_supports_shortreal_types() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-shortreal");
    let source_path = root.join("shortreal.sv");
    std::fs::write(
        &source_path,
        r#"
module shortreal_type_probe(
  input shortreal operand,
  output shortreal rounded,
  output shortreal sum,
  output shortreal negated,
  output shortreal quotient,
  output real widened,
  output int rounded_int,
  output logic greater,
  output string pattern,
  output string exponent,
  output string fixed,
  output string general
);
  initial rounded = 1.23456789;
  always @(*) begin
    sum = rounded + operand;
    negated = -rounded;
    quotient = 1.0 / operand;
    widened = rounded;
    rounded_int = rounded;
    greater = rounded > 1.0;
    pattern = $sformatf("%p", rounded);
    exponent = $sformatf("%e", rounded);
    fixed = $sformatf("%f", rounded);
    general = $sformatf("%g", rounded);
  end
endmodule
"#,
    )
    .expect("write shortreal source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("shortreal_type_probe"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower shortreal");

    assert!(design.net_decls.iter().any(|declaration| {
        declaration.name == "rounded" && declaration.width == 32 && declaration.is_signed
    }));

    let mut simulator = Simulator::new(&design).expect("create shortreal simulator");
    let rounded = 1.23456789_f64 as f32;
    for operand in [
        0.5_f32,
        f32::from_bits(1),
        f32::INFINITY,
        f32::from_bits(0x7fc0_0000),
    ] {
        simulator
            .set_input(
                "operand",
                &LogicWord::from_u64(32, u64::from(operand.to_bits())),
            )
            .expect("set shortreal operand");
        simulator
            .run_until(0)
            .expect("evaluate shortreal operations");

        fn shortreal_output(simulator: &Simulator, name: &str) -> f32 {
            let raw = u32::try_from(
                simulator
                    .read(name)
                    .unwrap_or_else(|| panic!("missing shortreal output {name}"))
                    .to_u64()
                    .unwrap_or_else(|| panic!("shortreal output {name} is unknown")),
            )
            .unwrap_or_else(|_| panic!("shortreal output {name} exceeds 32 bits"));
            f32::from_bits(raw)
        }

        assert_eq!(shortreal_output(&simulator, "rounded"), rounded);
        let sum = shortreal_output(&simulator, "sum");
        let expected_sum = rounded + operand;
        if expected_sum.is_nan() {
            assert!(
                sum.is_nan(),
                "unexpected shortreal sum for operand {operand:?}"
            );
        } else {
            assert_eq!(
                sum, expected_sum,
                "unexpected shortreal sum for operand {operand:?}"
            );
        }
        assert_eq!(
            shortreal_output(&simulator, "negated").to_bits(),
            (-rounded).to_bits()
        );
        let quotient = shortreal_output(&simulator, "quotient");
        if operand.is_nan() {
            assert!(quotient.is_nan());
        } else {
            assert_eq!(quotient, 1.0_f32 / operand);
        }
        let widened_bits = simulator.read("widened").unwrap().to_u64().unwrap();
        assert_eq!(f64::from_bits(widened_bits), f64::from(rounded));
        assert_eq!(simulator.read("rounded_int").unwrap().to_u64(), Some(1));
        assert_eq!(simulator.read("greater").unwrap().to_u64(), Some(1));
        assert_eq!(
            simulator
                .read("pattern")
                .unwrap()
                .to_ascii_string_nul_terminated(),
            format!("{}", f64::from(rounded))
        );
        assert_eq!(
            simulator
                .read("exponent")
                .unwrap()
                .to_ascii_string_nul_terminated(),
            "1.234568e+00"
        );
        assert_eq!(
            simulator
                .read("fixed")
                .unwrap()
                .to_ascii_string_nul_terminated(),
            "1.234568"
        );
        assert_eq!(
            simulator
                .read("general")
                .unwrap()
                .to_ascii_string_nul_terminated(),
            "1.23457"
        );
    }

    simulator
        .set_input(
            "operand",
            &LogicWord::from_u64(32, u64::from(0.0_f32.to_bits())),
        )
        .expect("set positive-zero shortreal divisor");
    simulator.run_until(0).expect("evaluate positive infinity");
    let positive = simulator.read("quotient").unwrap().to_u64().unwrap();
    assert_eq!(
        f32::from_bits(u32::try_from(positive).unwrap()),
        f32::INFINITY
    );

    simulator
        .set_input(
            "operand",
            &LogicWord::from_u64(32, u64::from(f32::from_bits(0x8000_0000).to_bits())),
        )
        .expect("set negative-zero shortreal divisor");
    simulator.run_until(0).expect("evaluate negative infinity");
    let negative = simulator.read("quotient").unwrap().to_u64().unwrap();
    assert_eq!(
        f32::from_bits(u32::try_from(negative).unwrap()),
        f32::NEG_INFINITY
    );

    let synthesis_path = root.join("shortreal_synthesis.sv");
    std::fs::write(
        &synthesis_path,
        r#"
module shortreal_synthesis(input shortreal source, output logic sink);
  assign sink = source != 0.0;
endmodule
"#,
    )
    .expect("write shortreal synthesis source");
    let synthesis_design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&synthesis_path),
            Some("shortreal_synthesis"),
            &PreprocessOptions::default(),
        )
        .expect("lower shortreal synthesis probe");
    let error = eda_synth::synthesize(&synthesis_design, &eda_synth::SynthOptions::default())
        .expect_err("shortreal synthesis must fail closed");
    assert!(
        error.contains("real comparisons are not synthesizable"),
        "unexpected shortreal synthesis error: {error}"
    );
}

#[test]
fn slang_ast_direct_lowering_supports_wildcard_package_imports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-package-import");
    let source_path = root.join("package_import.sv");
    std::fs::write(
        &source_path,
        r#"
package math_pkg;
  parameter int WIDTH = 8;
  localparam int OFFSET = 42;

  function automatic int double(input int value);
    double = 2 * value;
  endfunction
endpackage

module package_import
  import math_pkg::*;
#(
  parameter int EXTRA = 1
)(
  input logic [WIDTH-1:0] a,
  output logic [WIDTH-1:0] y,
  output int doubled_offset
);
  assign y = a + OFFSET;
  assign doubled_offset = double(OFFSET) + EXTRA;
endmodule
"#,
    )
    .expect("write package-import source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("package_import"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower wildcard package import");
    assert_eq!(design.assigns.len(), 2);
    let mut simulator = Simulator::new(&design).expect("create package-import simulator");
    simulator
        .set_input("a", &LogicWord::from_u64(8, 3))
        .unwrap();
    assert_eq!(simulator.read("y").unwrap().to_u64(), Some(45));
    assert_eq!(simulator.read("doubled_offset").unwrap().to_u64(), Some(85));

    let package_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("package_import"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize package-import AST");
    let package_summary = slang
        .summarize_ast_json(&package_json)
        .expect("summarize package-import AST");
    package_summary
        .validate_against_design(&design)
        .expect("exact inlined package-function fingerprints should match");

    let mut wrong_function_body = package_summary.clone();
    if let Some(target) = wrong_function_body
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "doubled_offset")
    {
        target.rhs.operands[0].operands[0].operands[0].literal = Some(format!("32:{:032b}", 3));
    }
    let function_body_error = wrong_function_body
        .validate_against_design(&design)
        .expect_err("wrong inlined package-function body must fail");
    assert!(
        function_body_error.contains("Mul:32:s[")
            && function_body_error.contains(&format!("Const:32:u[32:{:032b}]", 2))
            && function_body_error.contains(&format!("Const:32:u[32:{:032b}]", 3)),
        "unexpected inlined package-function body error: {function_body_error}"
    );

    let mut wrong_function_argument = package_summary;
    if let Some(target) = wrong_function_argument
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "doubled_offset")
    {
        target.rhs.operands[0].operands[0].operands[1].operands[0].symbol =
            Some("wrong_OFFSET".into());
    }
    let function_argument_error = wrong_function_argument
        .validate_against_design(&design)
        .expect_err("wrong inlined package-function argument must fail");
    assert!(
        function_argument_error.contains("Ref:32:s[wrong_OFFSET]")
            && function_argument_error.contains("Const:32:u[")
            && function_argument_error.contains("Mul:32:s["),
        "unexpected inlined package-function argument error: {function_argument_error}"
    );

    let explicit_path = root.join("explicit_import.sv");
    std::fs::write(
        &explicit_path,
        r#"
package scoped_pkg;
  parameter int WIDTH = 8;
  localparam int OFFSET = 21;

  function automatic int double(input int value);
    double = 2 * value;
  endfunction
endpackage

module explicit_import
  import scoped_pkg::WIDTH,
          scoped_pkg::OFFSET,
          scoped_pkg::double;
(
  input logic [WIDTH-1:0] a,
  output logic [WIDTH-1:0] imported,
  output logic [WIDTH-1:0] scoped,
  output int imported_function,
  output int scoped_function
);
  assign imported = a + OFFSET;
  assign scoped = a + scoped_pkg::OFFSET;
  assign imported_function = double(OFFSET);
  assign scoped_function = scoped_pkg::double(OFFSET);
endmodule
"#,
    )
    .expect("write explicit-import source");
    let explicit = slang
        .compile_files_via_ast(
            std::slice::from_ref(&explicit_path),
            Some("explicit_import"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower explicit package imports");
    assert_eq!(explicit.assigns.len(), 4);
    let mut explicit_simulator =
        Simulator::new(&explicit).expect("create explicit-import simulator");
    explicit_simulator
        .set_input("a", &LogicWord::from_u64(8, 3))
        .unwrap();
    assert_eq!(
        explicit_simulator.read("imported").unwrap().to_u64(),
        Some(24)
    );
    assert_eq!(
        explicit_simulator.read("scoped").unwrap().to_u64(),
        Some(24)
    );
    assert_eq!(
        explicit_simulator
            .read("imported_function")
            .unwrap()
            .to_u64(),
        Some(42)
    );
    assert_eq!(
        explicit_simulator.read("scoped_function").unwrap().to_u64(),
        Some(42)
    );

    let collision_path = root.join("package_collision.sv");
    std::fs::write(
        &collision_path,
        r#"
package left_pkg;
  parameter int SAME = 1;
endpackage

package right_pkg;
  parameter int SAME = 2;
endpackage

module package_collision
  import left_pkg::*,
          right_pkg::*;
(
  output int y
);
  assign y = 1;
endmodule
"#,
    )
    .expect("write package-collision source");
    let collision_error = slang
        .compile_files_via_ast(
            std::slice::from_ref(&collision_path),
            Some("package_collision"),
            &PreprocessOptions::default(),
        )
        .expect_err("ambiguous imported package names must fail closed");
    assert!(
        collision_error.contains("imported package symbol collision for 'SAME'"),
        "unexpected collision error: {collision_error}"
    );
}

#[test]
fn slang_ast_direct_lowering_supports_package_classes() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-package-classes");
    let source_path = root.join("package_classes.sv");
    std::fs::write(
        &source_path,
        r#"
package class_pkg;
  class Item;
    int value;

    function new(int v);
      value = v;
    endfunction

    function int get();
      return value;
    endfunction
  endclass

  class Registry extends Item;
    int extra;

    function new(int v, int e);
      super.new(v);
      extra = e;
    endfunction

    function int total();
      return value + extra;
    endfunction
  endclass
endpackage

module package_class_top(
  input int v,
  input int e,
  output int item_value,
  output int registry_total,
  output int registry_extra
);
  import class_pkg::Item,
          class_pkg::Registry;

  Item item;
  Registry registry;

  initial begin
    #1;
    item = new(v);
    registry = new(v, e);
    item_value = item.get();
    registry_total = registry.total();
    registry_extra = registry.extra;
  end
endmodule
"#,
    )
    .expect("write package-class source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("package_class_top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower package classes");
    let mut simulator = Simulator::new(&design).expect("create package-class simulator");
    simulator
        .set_input("v", &LogicWord::from_u64(32, 19))
        .unwrap();
    simulator
        .set_input("e", &LogicWord::from_u64(32, 23))
        .unwrap();
    simulator
        .run_until(1)
        .expect("run package-class initial block");
    assert_eq!(simulator.read("item_value").unwrap().to_u64(), Some(19));
    assert_eq!(simulator.read("registry_total").unwrap().to_u64(), Some(42));
    assert_eq!(simulator.read("registry_extra").unwrap().to_u64(), Some(23));

    let scoped_path = root.join("scoped_package_class.sv");
    std::fs::write(
        &scoped_path,
        r#"
package scoped_class_pkg;
  class Value;
    int value;

    function new(int v);
      value = v;
    endfunction

    function int get();
      return value;
    endfunction
  endclass
endpackage

module scoped_package_class_top(
  input int v,
  output int result
);
  scoped_class_pkg::Value object;

  initial begin
    #1;
    object = new(v);
    result = object.get();
  end
endmodule
"#,
    )
    .expect("write scoped package-class source");
    let scoped = slang
        .compile_files_via_ast(
            std::slice::from_ref(&scoped_path),
            Some("scoped_package_class_top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower package-scoped class references");
    let mut scoped_simulator =
        Simulator::new(&scoped).expect("create scoped package-class simulator");
    scoped_simulator
        .set_input("v", &LogicWord::from_u64(32, 55))
        .unwrap();
    scoped_simulator
        .run_until(1)
        .expect("run scoped package-class initial block");
    assert_eq!(scoped_simulator.read("result").unwrap().to_u64(), Some(55));

    let collision_path = root.join("package_class_collision.sv");
    std::fs::write(
        &collision_path,
        r#"
package left_class_pkg;
  class Same;
    int value;

    function new(int v);
      value = v;
    endfunction

    function int get();
      return value;
    endfunction
  endclass
endpackage

package right_class_pkg;
  class Same;
    int value;
  endclass
endpackage

module package_class_collision_top(
  input int v,
  output int result
);
  left_class_pkg::Same object;

  initial begin
    #1;
    object = new(v);
    result = object.get();
  end
endmodule
"#,
    )
    .expect("write duplicate package-class-name source");
    let duplicate_name = slang
        .compile_files_via_ast(
            std::slice::from_ref(&collision_path),
            Some("package_class_collision_top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower package-qualified duplicate class names");
    let mut duplicate_name_simulator = Simulator::new(&duplicate_name)
        .expect("create package-qualified duplicate-class simulator");
    duplicate_name_simulator
        .set_input("v", &LogicWord::from_u64(32, 77))
        .unwrap();
    duplicate_name_simulator
        .run_until(1)
        .expect("run package-qualified duplicate-class initial block");
    assert!(
        duplicate_name_simulator
            .read("result")
            .unwrap()
            .to_u64()
            .is_some_and(|value| value == 77),
        "package-qualified duplicate class selected the wrong definition"
    );
}

#[test]
fn slang_ast_direct_lowering_supports_simple_type_aliases_and_string_parameters() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-simple-type-aliases");
    let source_path = root.join("simple_type_aliases.sv");
    std::fs::write(
        &source_path,
        r#"
package types_pkg;
  typedef logic [15:0] wide_t;
  typedef int count_t;
  parameter string MESSAGE = "UVM";
endpackage

typedef int unsigned global_unsigned_t;
typedef logic [3:0] global_state_base_t;
typedef enum global_state_base_t {
  GLOBAL_A = 4'd1,
  GLOBAL_B = 4'd2
} global_state_t;

parameter int GLOBAL_PARAMETER = 13;
parameter global_state_t GLOBAL_STATE = GLOBAL_B;
int global_counter = 7;

function int global_add(int lhs);
  global_add = lhs + GLOBAL_PARAMETER;
endfunction

function void bump_global_counter();
  global_counter++;
endfunction

module type_alias_top
  import types_pkg::*;
(
  output wide_t wide,
  output count_t count,
  output string message,
  output real global_unsigned_as_real,
  output global_state_t global_state,
  output string global_state_name,
  output int global_parameter_value,
  output int global_function_value,
  output int global_variable_value,
  output int global_counter_after_bump
);
  global_unsigned_t global_unsigned = 32'hffff_ffff;
  assign wide = 16'h1234;
  assign count = 42;
  assign message = MESSAGE;
  assign global_state = GLOBAL_STATE;
  assign global_state_name = GLOBAL_STATE.name();
  initial global_unsigned_as_real = real'(global_unsigned);
  initial begin
    global_parameter_value = GLOBAL_PARAMETER;
    global_function_value = global_add(29);
    global_variable_value = global_counter;
    bump_global_counter();
    global_counter_after_bump = global_counter;
  end
endmodule
"#,
    )
    .expect("write simple-type-alias source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("type_alias_top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower simple type aliases");
    let simple_alias_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("type_alias_top"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize simple-type-alias AST");
    let mut simple_alias_summary = slang
        .summarize_ast_json(&simple_alias_json)
        .expect("summarize simple-type-alias AST");
    simple_alias_summary
        .validate_against_design(&design)
        .expect("exact simple-type-alias fingerprints should match");
    if let Some(target) = simple_alias_summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "wide")
    {
        target.rhs.operands[0].literal = Some("16:0001001000110101".into());
    }
    let simple_alias_error = simple_alias_summary
        .validate_against_design(&design)
        .expect_err("wrong simple-type-alias literal must fail");
    assert!(
        simple_alias_error.contains("Const:16:u[16:0001001000110100]")
            && simple_alias_error.contains("Const:16:u[16:0001001000110101]"),
        "unexpected simple-type-alias error: {simple_alias_error}"
    );
    let mut simulator = Simulator::new(&design).expect("create type-alias simulator");
    simulator.run_until(0).expect("run type-alias assignments");
    assert_eq!(simulator.read("wide").unwrap().to_u64(), Some(0x1234));
    assert_eq!(simulator.read("count").unwrap().to_u64(), Some(42));
    assert_eq!(
        simulator
            .read("message")
            .unwrap()
            .to_ascii_string_nul_terminated(),
        "UVM"
    );
    let global_bits = simulator
        .read("global_unsigned_as_real")
        .unwrap()
        .to_u64()
        .expect("global unsigned conversion is known");
    assert_eq!(f64::from_bits(global_bits), u32::MAX as f64);
    assert_eq!(simulator.read("global_state").unwrap().to_u64(), Some(2));
    assert_eq!(
        simulator
            .read("global_state_name")
            .unwrap()
            .to_ascii_string_nul_terminated(),
        "GLOBAL_B"
    );
    assert_eq!(
        simulator.read("global_parameter_value").unwrap().to_u64(),
        Some(13)
    );
    assert_eq!(
        simulator.read("global_function_value").unwrap().to_u64(),
        Some(42)
    );
    assert_eq!(
        simulator.read("global_variable_value").unwrap().to_u64(),
        Some(7)
    );
    assert_eq!(
        simulator
            .read("global_counter_after_bump")
            .unwrap()
            .to_u64(),
        Some(8)
    );
}

#[test]
fn slang_ast_direct_lowering_supports_package_typedefs_and_enums() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-package-types");
    let source_path = root.join("package_types.sv");
    std::fs::write(
        &source_path,
        r#"
package types_pkg;
  typedef enum logic [1:0] {
    A = 2'd1,
    B = 2'd2
  } state_t;

  typedef struct packed {
    logic [3:0] high;
    logic [3:0] low;
  } pair_t;

  localparam state_t INIT = A;
endpackage

module package_types
  import types_pkg::*;
(
  input logic [1:0] selector,
  input logic [7:0] data,
  output state_t state,
  output pair_t pair,
  output state_t next_state,
  output state_t previous_state,
  output state_t first_state,
  output state_t last_state,
  output int enum_count,
  output string state_name,
  output logic initialized,
  output logic selected_a
);
  assign state = selector[0] ? B : A;
  assign pair = data;
  assign next_state = state.next();
  assign previous_state = state.prev();
  assign first_state = state.first();
  assign last_state = state.last();
  assign enum_count = state.num();
  assign state_name = state.name();
  assign initialized = (INIT == A);
  assign selected_a = (state == A);
endmodule
"#,
    )
    .expect("write package-typedef source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("package_types"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower package typedefs and enums");
    assert_eq!(design.assigns.len(), 10);
    let mut simulator = Simulator::new(&design).expect("create package-type simulator");
    simulator
        .set_input("selector", &LogicWord::from_u64(2, 0))
        .unwrap();
    simulator
        .set_input("data", &LogicWord::from_u64(8, 0x5A))
        .unwrap();
    assert_eq!(simulator.read("state").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("pair").unwrap().to_u64(), Some(0x5A));
    assert_eq!(simulator.read("next_state").unwrap().to_u64(), Some(2));
    assert_eq!(simulator.read("previous_state").unwrap().to_u64(), Some(2));
    assert_eq!(simulator.read("first_state").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("last_state").unwrap().to_u64(), Some(2));
    assert_eq!(simulator.read("enum_count").unwrap().to_u64(), Some(2));
    assert_eq!(
        simulator
            .read("state_name")
            .unwrap()
            .to_ascii_string_nul_terminated(),
        "A"
    );
    assert_eq!(simulator.read("initialized").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("selected_a").unwrap().to_u64(), Some(1));
}

#[test]
fn slang_ast_direct_lowering_compiles_procedural_control_flow() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-procedural");
    let source_path = root.join("procedural.sv");
    std::fs::write(
        &source_path,
        r#"
module procedural(
  input logic a,
  input logic clk,
  input logic [1:0] sel,
  output logic y,
  output logic z,
  output logic q
);
  initial q = 1'b0;
  always_comb begin
    if (a) begin
      y = 1'b1;
    end else begin
      y = 1'b0;
    end
    case (sel)
      2'b00: z = 1'b0;
      2'b01: z = 1'b1;
      default: z = a;
    endcase
  end
  always @(posedge clk) q <= a;
endmodule
"#,
    )
    .expect("write procedural direct-lowering source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("procedural"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower procedural slang AST");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("procedural"),
            &PreprocessOptions::default(),
        )
        .expect("lower procedural module through the preprocessed path");
    assert_eq!(design.n_nets, 7);
    assert_eq!(design.initials.len(), 1);
    assert_eq!(design.processes.len(), 2);
    assert_eq!(
        format!("{:?}", reference.initials),
        format!("{:?}", design.initials)
    );
    assert_eq!(
        format!("{:?}", reference.processes),
        format!("{:?}", design.processes)
    );

    let mut simulator = Simulator::new(&design).expect("create procedural simulator");
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize clk low");
    simulator
        .set_input("a", &LogicWord::from_u64(1, 1))
        .expect("set a");
    simulator
        .set_input("sel", &LogicWord::from_u64(2, 2))
        .expect("set default case selector");
    assert_eq!(simulator.read("q").unwrap().to_u64(), Some(0));
    assert_eq!(simulator.read("y").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("z").unwrap().to_u64(), Some(1));
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create posedge");
    assert_eq!(simulator.read("q").unwrap().to_u64(), Some(1));

    let mixed_event_path = root.join("mixed-event.sv");
    std::fs::write(
        &mixed_event_path,
        r#"
module mixed_event(input logic a, input logic clk, output logic y);
  always @(posedge clk or a) y = a;
endmodule
"#,
    )
    .expect("write mixed-event source");
    let mixed_event = slang
        .compile_files_via_ast(
            std::slice::from_ref(&mixed_event_path),
            Some("mixed_event"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower mixed edge/level sensitivity");
    assert!(
        matches!(
            &mixed_event.processes[0].sens,
            eda_core::ir::Sens::List(list)
                if matches!(list.as_slice(), [eda_core::ir::Sens::Posedge(_), eda_core::ir::Sens::Any(_)])
        ),
        "unexpected sensitivity: {:?}",
        mixed_event.processes[0].sens
    );
}

#[test]
fn slang_ast_direct_lowering_flattens_simple_hierarchy() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-hierarchy");
    let source_path = root.join("hierarchy.sv");
    std::fs::write(
        &source_path,
        r#"
module child #(parameter W = 4)
    (input logic [W-1:0] a, output logic [W-1:0] y, output logic held);
  assign y = ~a;
  initial held = 1'b1;
endmodule

module top(input logic [3:0] a, output logic [3:0] y, output logic held);
  child #(.W(4)) u (.a(a), .y(y), .held(held));
endmodule
"#,
    )
    .expect("write hierarchy source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower simple hierarchy");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("lower hierarchy through the preprocessed path");
    assert_eq!(
        design.n_nets, 18,
        "direct declarations: {:?}; reference declarations: {:?}",
        design.net_decls, reference.net_decls
    );
    assert_eq!(design.assigns.len(), 4);
    assert_eq!(design.initials.len(), 1);
    assert_eq!(design.hierarchy.len(), 2);
    assert_eq!(
        format!("{:?}", reference.net_decls),
        format!("{:?}", design.net_decls)
    );
    assert_eq!(
        format!("{:?}", reference.assigns),
        format!("{:?}", design.assigns)
    );
    assert_eq!(
        format!("{:?}", reference.initials),
        format!("{:?}", design.initials)
    );
    assert_eq!(
        format!("{:?}", reference.hierarchy),
        format!("{:?}", design.hierarchy)
    );

    let mut simulator = Simulator::new(&design).expect("create hierarchy simulator");
    simulator
        .set_input("a", &LogicWord::from_u64(4, 0b1010))
        .expect("set hierarchy input");
    assert_eq!(simulator.read("y").unwrap().to_u64(), Some(0b0101));
    assert_eq!(simulator.read("held").unwrap().to_u64(), Some(1));

    let nested_path = root.join("nested.sv");
    std::fs::write(
        &nested_path,
        r#"
module leaf(input logic a, output logic y); assign y = a; endmodule
module middle(input logic a, output logic y); leaf u (.a(a), .y(y)); endmodule
module top(input logic a, output logic y); middle u (.a(a), .y(y)); endmodule
"#,
    )
    .expect("write nested hierarchy source");
    let nested_design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&nested_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower nested hierarchy");
    let nested_reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&nested_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("lower nested hierarchy through the preprocessed path");
    assert_eq!(nested_design.n_nets, 6);
    assert_eq!(nested_design.assigns.len(), 5);
    assert_eq!(nested_design.hierarchy.len(), 3);
    assert!(
        nested_design
            .hierarchy
            .iter()
            .any(|instance| instance.path == "top.u.u"),
        "unexpected hierarchy: {:?}",
        nested_design.hierarchy
    );
    assert_eq!(
        format!("{:?}", nested_reference.net_decls),
        format!("{:?}", nested_design.net_decls)
    );
    assert_eq!(
        format!("{:?}", nested_reference.assigns),
        format!("{:?}", nested_design.assigns)
    );
    assert_eq!(
        format!("{:?}", nested_reference.hierarchy),
        format!("{:?}", nested_design.hierarchy)
    );

    let mut nested_simulator = Simulator::new(&nested_design).expect("create nested simulator");
    nested_simulator
        .set_input("a", &LogicWord::from_u64(1, 1))
        .expect("set nested input");
    assert_eq!(nested_simulator.read("y").unwrap().to_u64(), Some(1));
    nested_simulator
        .set_input("a", &LogicWord::from_u64(1, 0))
        .expect("update nested input");
    assert_eq!(nested_simulator.read("y").unwrap().to_u64(), Some(0));
}

#[test]
fn slang_ast_direct_lowering_uses_sparse_memory_operations() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory");
    let source_path = root.join("memory.sv");
    std::fs::write(
        &source_path,
        r#"
module memory(
  input logic clk,
  input logic write,
  input logic [1:0] addr,
  input logic [7:0] wdata,
  output logic [7:0] rdata
);
  logic [7:0] mem [0:3];
  initial begin
    mem[0] = 8'h11;
    mem[1] = 8'h22;
  end
  always_comb rdata = mem[addr];
  always @(posedge clk) begin
    if (write) mem[addr] <= wdata;
  end
endmodule
"#,
    )
    .expect("write sparse-memory source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower sparse memory");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("memory"),
            &PreprocessOptions::default(),
        )
        .expect("lower sparse memory through the preprocessed path");
    assert_eq!(design.memories.len(), 1);
    assert_eq!(
        design.memories[0].storage,
        eda_core::ir::MemoryStorage::Sparse
    );
    assert_eq!(design.memories[0].name, "mem");
    assert_eq!(design.memories[0].element_width, 8);
    assert_eq!(design.memories[0].flat_length, 4);
    assert_eq!(design.memories[0].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(
        design.memories[0].template,
        eda_core::ir::MemoryTemplate::SyncRam
    );
    assert!(design.memories[0]
        .write_mask
        .as_ref()
        .expect("runtime memory write mask")
        .is_full());
    assert_eq!(
        design.memories[0].byte_enable,
        Some(eda_core::ir::MemoryByteEnable::full(8))
    );
    assert!(reference.memories.is_empty());
    assert_eq!(
        format!("{:?}", reference.ports),
        format!("{:?}", design.ports)
    );
    let reference_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize legacy-array AST");
    let mut reference_summary = slang
        .summarize_ast_json(&reference_json)
        .expect("summarize legacy-array AST");
    reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect("exact dynamic array lvalue fingerprint should match");
    if let Some(assignment) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .dynamic_array_lvalue_indexes
                    .first()
                    .is_some_and(|selector| selector.symbol.as_deref() == Some("addr"))
            })
        })
    {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("wrong_addr".into());
    }
    let selector_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic array selector must fail");
    assert!(
        selector_error.contains("Ref:2:u[wrong_addr]") && selector_error.contains("Ref:2:u[addr]"),
        "unexpected dynamic array selector error: {selector_error}"
    );
    if let Some(assignment) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .dynamic_array_lvalue_indexes
                    .first()
                    .is_some_and(|selector| selector.symbol.as_deref() == Some("wrong_addr"))
            })
        })
    {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("addr".into());
        assignment.rhs.symbol = Some("wrong_data".into());
    }
    let value_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic array value must fail");
    assert!(
        value_error.contains("Ref:8:u[wrong_data]") && value_error.contains("Ref:8:u[wdata]"),
        "unexpected dynamic array value error: {value_error}"
    );
    if let Some(assignment) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .dynamic_array_lvalue_indexes
                    .first()
                    .is_some_and(|selector| selector.symbol.as_deref() == Some("addr"))
            })
        })
    {
        assignment.rhs.symbol = Some("wdata".into());
    }
    let mut simulator = Simulator::new(&design).expect("create sparse-memory simulator");
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize clk");
    simulator
        .set_input("write", &LogicWord::from_u64(1, 0))
        .expect("initialize write");
    simulator
        .set_input("addr", &LogicWord::from_u64(2, 0))
        .expect("select initialized element");
    assert_eq!(simulator.read("rdata").unwrap().to_u64(), Some(0x11));

    simulator
        .set_input("addr", &LogicWord::from_u64(2, 2))
        .expect("select write element");
    simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0xaa))
        .expect("set write data");
    simulator
        .set_input("write", &LogicWord::from_u64(1, 1))
        .expect("request write");
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create sparse-memory posedge");
    assert_eq!(simulator.read("rdata").unwrap().to_u64(), Some(0xaa));

    simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("reset clk");
    simulator
        .set_input("addr", &LogicWord::from_u64(2, 1))
        .expect("select another initialized element");
    assert_eq!(simulator.read("rdata").unwrap().to_u64(), Some(0x22));

    simulator
        .set_input("addr", &LogicWord::from_u64(2, 2))
        .expect("select overwritten element");
    assert_eq!(simulator.read("rdata").unwrap().to_u64(), Some(0xaa));

    simulator
        .set_input("addr", &LogicWord::from_u64(2, 3))
        .expect("select out-of-range element");
    assert_eq!(simulator.read("rdata").unwrap().to_u64(), None);

    let mut reference_simulator =
        Simulator::new(&reference).expect("create legacy-array simulator");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize legacy clk");
    reference_simulator
        .set_input("write", &LogicWord::from_u64(1, 0))
        .expect("initialize legacy write");
    reference_simulator
        .set_input("addr", &LogicWord::from_u64(2, 0))
        .expect("select initialized legacy element");
    assert_eq!(
        reference_simulator.read("rdata").unwrap().to_u64(),
        Some(0x11)
    );
    reference_simulator
        .set_input("addr", &LogicWord::from_u64(2, 2))
        .expect("select legacy write element");
    reference_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0xaa))
        .expect("set legacy write data");
    reference_simulator
        .set_input("write", &LogicWord::from_u64(1, 1))
        .expect("request legacy write");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create legacy posedge");
    assert_eq!(
        reference_simulator.read("rdata").unwrap().to_u64(),
        Some(0xaa)
    );
}

#[test]
fn slang_ast_summary_rejects_wrong_sparse_memory_read_and_part_shapes() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory-summary");
    let source_path = root.join("memory_summary.sv");
    std::fs::write(
        &source_path,
        r#"
module memory_summary(
  input logic [1:0] address,
  input logic [1:0] start,
  output logic [7:0] data,
  output logic [3:0] part
);
  logic [7:0] memory [0:3];
  assign data = memory[address];
  assign part = memory[address][start +: 4];
endmodule
"#,
    )
    .expect("write sparse-memory summary source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory_summary"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower sparse-memory summary source");
    let json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory_summary"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize authoritative sparse-memory AST");
    let mut summary = slang
        .summarize_ast_json(&json)
        .expect("summarize authoritative sparse-memory AST");
    summary
        .validate_against_design(&design)
        .expect("exact sparse-memory read fingerprint should match");

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "data")
    {
        target.rhs.operands[1].symbol = Some("0 wrong_address".into());
    }
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong sparse-memory index must fail structural validation");
    assert!(
        error.contains("MemoryRead:") && error.contains("wrong_address"),
        "unexpected structural error: {error}"
    );

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "data")
    {
        target.rhs.operands[1].symbol = Some("address".into());
    }
    summary
        .validate_against_design(&design)
        .expect("restored whole-element read should match");
    let part = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "part")
        .expect("sparse-memory part-read target");
    part.rhs.operands[1].symbol = Some("0 wrong_start".into());
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong sparse-memory part start must fail structural validation");
    assert!(
        error.contains("MemoryReadPart:") && error.contains("wrong_start"),
        "unexpected structural error: {error}"
    );
}

#[test]
fn slang_ast_summary_rejects_wrong_packed_select_shapes() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-packed-summary");
    let source_path = root.join("packed_summary.sv");
    std::fs::write(
        &source_path,
        r#"
module packed_summary(
  input logic [7:0] data,
  input logic [0:7] ascending,
  input logic [2:0] selector,
  input logic [3:0][7:0] groups,
  input logic [0:3][0:7] ascending_groups,
  input logic signed [2:0] signed_selector,
  input logic [-4:3] negative_range,
  output logic bit_one,
  output logic [3:0] high,
  output logic [3:0] up,
  output logic [3:0] down,
  output logic [3:0] ascending_up,
  output logic dynamic_bit,
  output logic [7:0] dynamic_group,
  output logic [7:0] ascending_dynamic_group,
  output logic negative_dynamic
);
  assign bit_one = data[1];
  assign high = data[7:4];
  assign up = data[3 +: 4];
  assign down = data[6 -: 4];
  assign ascending_up = ascending[0 +: 4];
  assign dynamic_bit = data[selector];
  assign dynamic_group = groups[selector];
  assign ascending_dynamic_group = ascending_groups[selector];
  assign negative_dynamic = negative_range[signed_selector];
endmodule
"#,
    )
    .expect("write packed-select summary source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("packed_summary"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower packed-select summary source");
    let json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("packed_summary"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize authoritative packed-select AST");
    let mut summary = slang
        .summarize_ast_json(&json)
        .expect("summarize authoritative packed-select AST");
    summary
        .validate_against_design(&design)
        .expect("constant packed-select fingerprints should match");

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "bit_one")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000010".into());
    }
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong constant packed bit index must fail structural validation");
    assert!(
        error.contains("PackedSelect:") && error.contains("Range:2:2"),
        "unexpected structural error: {error}"
    );

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "bit_one")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000001".into());
    }
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "high")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000111".into());
    }
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "up")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000010".into());
    }
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong constant indexed packed select start must fail");
    assert!(
        error.contains("PackedSelect:") && error.contains("Range:5:2"),
        "unexpected structural error: {error}"
    );

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "up")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000011".into());
    }
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "down")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000101".into());
    }
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong constant descending packed select start must fail");
    assert!(
        error.contains("PackedSelect:") && error.contains("Range:5:2"),
        "unexpected structural error: {error}"
    );

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "down")
    {
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000110".into());
    }

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "dynamic_bit")
    {
        target.rhs.operands[1].symbol = Some("wrong_selector".into());
    }
    let error = summary
        .validate_against_design(&design)
        .expect_err("wrong dynamic packed selector must fail structural validation");
    assert!(
        error.contains("Eq:1:u[Ref:3:u[wrong_selector],"),
        "unexpected structural error: {error}"
    );
}

#[test]
fn slang_ast_direct_lowering_uses_sparse_memory_part_selects() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory-parts");
    let source_path = root.join("memory-parts.sv");
    std::fs::write(
        &source_path,
        r#"
module memory_parts(
  input logic clk,
  input logic [2:0] start,
  input logic [7:0] data,
  input logic [1:0] raddr,
  output logic [3:0] simple,
  output logic [3:0] up,
  output logic [3:0] down,
  output logic [3:0] updated
);
  logic [7:0] mem [0:3];
  initial begin
    mem[0] = 8'h9c;
    mem[1] = 8'h22;
  end
  assign simple = mem[0][0 +: 4];
  assign up = mem[0][2 +: 4];
  assign down = mem[0][6 -: 4];
  assign updated = mem[raddr][start +: 4];
  always @(posedge clk) begin
    mem[1][start +: 4] <= data[3:0];
  end
endmodule
"#,
    )
    .expect("write sparse-memory part-select source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory_parts"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower sparse-memory part selects");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("memory_parts"),
            &PreprocessOptions::default(),
        )
        .expect("lower sparse-memory part selects through the preprocessed path");
    let reference_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory_parts"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize bounded part-select AST");
    let mut reference_summary = slang
        .summarize_ast_json(&reference_json)
        .expect("summarize bounded part-select AST");
    reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect("exact bounded array part-write fingerprint should match");
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.indexes[0].literal = Some("32:00000000000000000000000000000000".into());
    }
    let index_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong array part element index must fail");
    assert!(
        index_error.contains("Offset:0") && index_error.contains("Offset:8"),
        "unexpected array part index error: {index_error}"
    );
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.indexes[0].literal = Some("32:00000000000000000000000000000001".into());
        part.start.symbol = Some("wrong_start".into());
    }
    let start_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong array part start must fail");
    assert!(
        start_error.contains("Ref:3:u[wrong_start]") && start_error.contains("Ref:3:u[start]"),
        "unexpected array part start error: {start_error}"
    );
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.start.symbol = Some("start".into());
        part.width = 3;
    }
    let width_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong array part width must fail closed");
    assert!(
        width_error.contains("could not fingerprint array part lvalue 'mem'"),
        "unexpected array part width error: {width_error}"
    );
    if let Some(assignment) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find(|assignment| assignment.array_part_lvalue.is_some())
        })
    {
        assignment.array_part_lvalue.as_mut().unwrap().width = 4;
        assignment.rhs.operands[0].symbol = Some("wrong_data".into());
    }
    let value_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong array part value must fail");
    assert!(
        value_error.contains("PackedSelect:4:u[Ref:8:u[wrong_data]")
            && value_error.contains("PackedSelect:4:u[Ref:8:u[data]"),
        "unexpected array part value error: {value_error}"
    );
    assert_eq!(design.memories.len(), 1);
    assert_eq!(design.assigns.len(), 4);
    assert_eq!(design.initials.len(), 1);
    assert_eq!(design.initials.len(), 1);
    assert!(design.memories[0]
        .write_mask
        .as_ref()
        .expect("dynamic part writes require a conservative mask")
        .is_full());

    let mut simulator = Simulator::new(&design).expect("create part-select simulator");
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize clk");
    simulator
        .set_input("start", &LogicWord::from_u64(3, 2))
        .expect("set part-select start");
    simulator
        .set_input("raddr", &LogicWord::from_u64(2, 1))
        .expect("set read element");
    assert_eq!(simulator.read("simple").unwrap().to_u64(), Some(0b1100));
    assert_eq!(simulator.read("up").unwrap().to_u64(), Some(0b0111));
    assert_eq!(simulator.read("down").unwrap().to_u64(), Some(0b0011));
    assert_eq!(simulator.read("updated").unwrap().to_u64(), Some(0b1000));

    simulator
        .set_input("data", &LogicWord::from_u64(8, 0b1011))
        .expect("set part-write data");
    simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create part-write posedge");
    assert_eq!(simulator.read("updated").unwrap().to_u64(), Some(0b1011));

    let mut reference_simulator =
        Simulator::new(&reference).expect("create legacy part-select simulator");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize legacy clk");
    reference_simulator
        .set_input("start", &LogicWord::from_u64(3, 2))
        .expect("set legacy part-select start");
    reference_simulator
        .set_input("raddr", &LogicWord::from_u64(2, 1))
        .expect("set legacy read element");
    assert_eq!(
        reference_simulator.read("simple").unwrap().to_u64(),
        Some(0b1100)
    );
    assert_eq!(
        reference_simulator.read("up").unwrap().to_u64(),
        Some(0b0111)
    );
    assert_eq!(
        reference_simulator.read("down").unwrap().to_u64(),
        Some(0b0011)
    );
    assert_eq!(
        reference_simulator.read("updated").unwrap().to_u64(),
        Some(0b1000)
    );
    reference_simulator
        .set_input("data", &LogicWord::from_u64(8, 0b1011))
        .expect("set legacy part-write data");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create legacy part-write posedge");
    assert_eq!(
        reference_simulator.read("updated").unwrap().to_u64(),
        Some(0b1011)
    );

    let simple_path = root.join("simple-part.sv");
    std::fs::write(
        &simple_path,
        r#"
module simple_part(output logic [3:0] y);
  logic [7:0] mem [0:0];
  initial begin
    mem[0] = 8'h9c;
  end
  assign y = mem[0][3:0];
endmodule
"#,
    )
    .expect("write simple memory part-select source");
    let simple_design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&simple_path),
            Some("simple_part"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower simple memory part select");
    let mut simple_simulator =
        Simulator::new(&simple_design).expect("create simple part-select simulator");
    simple_simulator
        .run_until(0)
        .expect("settle simple part-select outputs");
    assert_eq!(simple_simulator.read("y").unwrap().to_u64(), Some(0b1100));
}

#[test]
fn slang_ast_summary_uses_reversed_dynamic_array_fingerprints() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("reversed-dynamic-array");
    let source_path = root.join("reversed_dynamic_array.sv");
    std::fs::write(
        &source_path,
        r#"
module reversed_dynamic_array(
  input logic clk,
  input logic [1:0] addr,
  input logic [7:0] wdata,
  output logic [7:0] q
);
  logic [0:7] mem [0:3];
  initial begin
    mem[0] = 8'h12;
    mem[3] = 8'h34;
  end
  always @(posedge clk) mem[addr] <= wdata;
  assign q = mem[addr];
endmodule
"#,
    )
    .expect("write reversed dynamic array source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("reversed_dynamic_array"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower reversed dynamic array");
    let bounded = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("reversed_dynamic_array"),
            &PreprocessOptions::default(),
        )
        .expect("lower reversed dynamic array through bounded path");
    let json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("reversed_dynamic_array"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize reversed dynamic array AST");
    let mut summary = slang
        .summarize_ast_json(&json)
        .expect("summarize reversed dynamic array AST");
    summary
        .validate_against_design(&direct)
        .expect("exact direct reversed dynamic fingerprint should match");
    summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect("exact bounded reversed dynamic fingerprint should match");
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "q")
    {
        target.rhs.operands[1].symbol = Some("wrong_addr".into());
    }
    let continuous_read_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong reversed continuous read selector must fail");
    assert!(
        continuous_read_error.contains("Ref:2:u[wrong_addr]")
            && continuous_read_error.contains("Ref:2:u[addr]")
            && continuous_read_error.contains("Cond:8:u[")
            && continuous_read_error.contains("Concat:8:u["),
        "unexpected reversed continuous read error: {continuous_read_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "q")
    {
        target.rhs.operands[1].symbol = Some("addr".into());
    }
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| !assignment.dynamic_array_lvalue_indexes.is_empty())
    }) {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("wrong_addr".into());
    }
    let selector_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong reversed dynamic selector must fail");
    assert!(
        selector_error.contains("Ref:2:u[wrong_addr]")
            && selector_error.contains("Ref:2:u[addr]")
            && selector_error.contains("GuardedArrayPartWrite:8:u[")
            && selector_error.contains("Reversed:true"),
        "unexpected reversed selector error: {selector_error}"
    );
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| !assignment.dynamic_array_lvalue_indexes.is_empty())
    }) {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("addr".into());
        assignment.rhs.symbol = Some("wrong_data".into());
    }
    let value_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong reversed dynamic value must fail");
    assert!(
        value_error.contains("Ref:8:u[wrong_data]")
            && value_error.contains("Ref:8:u[wdata]")
            && value_error.contains("GuardedArrayPartWrite:8:u["),
        "unexpected reversed value error: {value_error}"
    );
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| !assignment.dynamic_array_lvalue_indexes.is_empty())
    }) {
        assignment.rhs.symbol = Some("wdata".into());
    }
    assert_eq!(direct.memories.len(), 1);
    assert!(bounded.memories.is_empty());

    let mut direct_simulator =
        Simulator::new(&direct).expect("create direct reversed-array simulator");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize direct clock");
    direct_simulator
        .set_input("addr", &LogicWord::from_u64(2, 3))
        .expect("select direct reversed element");
    direct_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0xd7))
        .expect("set direct reversed data");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x34));
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create direct reversed posedge");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0xd7));

    let mut bounded_simulator =
        Simulator::new(&bounded).expect("create bounded reversed-array simulator");
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize bounded clock");
    bounded_simulator
        .set_input("addr", &LogicWord::from_u64(2, 3))
        .expect("select bounded reversed element");
    bounded_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0xd7))
        .expect("set bounded reversed data");
    assert_eq!(bounded_simulator.read("q").unwrap().to_u64(), Some(0x34));
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create bounded reversed posedge");
    assert_eq!(bounded_simulator.read("q").unwrap().to_u64(), Some(0xd7));
}

#[test]
fn slang_ast_summary_uses_wide_dynamic_array_fingerprints() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("wide-dynamic-array-parts");
    let source_path = root.join("wide_dynamic_array.sv");
    std::fs::write(
        &source_path,
        r#"
module wide_dynamic_array(
  input logic clk,
  input logic [2:0] addr,
  input logic [2:0] start,
  input logic [7:0] wdata,
  output logic [7:0] whole,
  output logic [7:0] indexed_whole,
  output logic [3:0] part
);
  logic [7:0] mem [0:4];
  initial begin
    mem[0] = 8'h12;
    mem[4] = 8'h34;
  end
  always @(posedge clk) begin
    mem[addr] <= wdata;
    mem[addr][start +: 4] <= wdata[3:0];
  end
  assign whole = mem[addr];
  assign indexed_whole = mem[addr][0 +: 8];
  assign part = mem[addr][start +: 4];
endmodule
"#,
    )
    .expect("write wide dynamic array source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("wide_dynamic_array"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower wide dynamic array");
    let bounded = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("wide_dynamic_array"),
            &PreprocessOptions::default(),
        )
        .expect("lower wide dynamic array through bounded path");
    assert_eq!(direct.memories.len(), 1);
    assert!(bounded.memories.is_empty());
    let json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("wide_dynamic_array"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize wide dynamic array AST");
    let mut summary = slang
        .summarize_ast_json(&json)
        .expect("summarize wide dynamic array AST");
    summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect("exact wide dynamic array fingerprints should match");

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "whole")
    {
        target.rhs.operands[1].symbol = Some("wrong_addr".into());
    }
    let continuous_read_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong continuous wide array read selector must fail");
    assert!(
        continuous_read_error.contains("Ref:3:u[wrong_addr]")
            && continuous_read_error.contains("Ref:3:u[addr]")
            && continuous_read_error.contains("Cond:40:u["),
        "unexpected continuous read error: {continuous_read_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "whole")
    {
        target.rhs.operands[1].symbol = Some("addr".into());
    }

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "indexed_whole")
    {
        target.rhs.operands[0].operands[1].symbol = Some("wrong_addr".into());
    }
    let indexed_whole_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong canonical indexed whole-element selector must fail");
    assert!(
        indexed_whole_error.contains("Ref:3:u[wrong_addr]")
            && indexed_whole_error.contains("Ref:3:u[addr]")
            && indexed_whole_error.contains("Cond:40:u["),
        "unexpected indexed whole-element error: {indexed_whole_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "indexed_whole")
    {
        target.rhs.operands[0].operands[1].symbol = Some("addr".into());
    }

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "part")
    {
        target.rhs.operands[0].operands[1].symbol = Some("wrong_addr".into());
    }
    let part_read_index_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong continuous wide array part-read selector must fail");
    assert!(
        part_read_index_error.contains("Ref:3:u[wrong_addr]")
            && part_read_index_error.contains("Ref:3:u[addr]")
            && part_read_index_error.contains("Cond:8:u["),
        "unexpected continuous part-read index error: {part_read_index_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "part")
    {
        target.rhs.operands[0].operands[1].symbol = Some("addr".into());
        target.rhs.operands[1].symbol = Some("wrong_start".into());
    }
    let part_read_start_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong continuous wide array part-read start must fail");
    assert!(
        part_read_start_error.contains("Ref:3:u[wrong_start]")
            && part_read_start_error.contains("Ref:3:u[start]")
            && part_read_start_error.contains("Cond:8:u["),
        "unexpected continuous part-read start error: {part_read_start_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "part")
    {
        target.rhs.operands[1].symbol = Some("start".into());
        target.rhs.type_width = Some(3);
        target.rhs.operands[2].literal = Some("32:011".into());
    }
    let part_read_width_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong continuous wide array part-read width must fail");
    assert!(
        part_read_width_error.contains("Const:3:u[3:111]")
            && part_read_width_error.contains("Const:4:u[4:1111]"),
        "unexpected continuous part-read width error: {part_read_width_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "part")
    {
        target.rhs.type_width = Some(4);
        target.rhs.operands[2].literal = Some("32:00000000000000000000000000000100".into());
    }

    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| assignment.dynamic_array_lvalue_indexes.len() == 1)
    }) {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("wrong_addr".into());
    }
    let whole_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong wide whole-element selector must fail");
    assert!(
        whole_error.contains("Ref:3:u[wrong_addr]")
            && whole_error.contains("Ref:3:u[addr]")
            && whole_error.contains("Cond:40:u["),
        "unexpected wide whole-element error: {whole_error}"
    );
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| assignment.dynamic_array_lvalue_indexes.len() == 1)
    }) {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("addr".into());
        assignment.rhs.symbol = Some("wrong_data".into());
    }
    let whole_value_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong wide whole-element value must fail");
    assert!(
        whole_value_error.contains("Ref:8:u[wrong_data]")
            && whole_value_error.contains("Ref:8:u[wdata]")
            && whole_value_error.contains("Cond:40:u["),
        "unexpected wide whole-value error: {whole_value_error}"
    );
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| assignment.array_part_lvalue.is_some())
    }) {
        assignment.rhs.symbol = Some("wdata".into());
        assignment.array_part_lvalue.as_mut().unwrap().start.symbol = Some("wrong_start".into());
    }
    let part_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong wide part start must fail");
    assert!(
        part_error.contains("Ref:3:u[wrong_start]")
            && part_error.contains("Ref:3:u[start]")
            && part_error.contains("GuardedArrayPartWrite:4:u["),
        "unexpected wide part error: {part_error}"
    );
    if let Some(part) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find_map(|assignment| assignment.array_part_lvalue.as_mut())
    }) {
        part.start.symbol = Some("start".into());
        part.width = 3;
    }
    let width_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong wide part width must fail closed");
    assert!(
        width_error.contains("could not fingerprint array part lvalue 'mem'"),
        "unexpected wide part width error: {width_error}"
    );
    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| assignment.array_part_lvalue.is_some())
    }) {
        assignment.array_part_lvalue.as_mut().unwrap().width = 4;
        assignment.rhs.operands[0].symbol = Some("wrong_data".into());
    }
    let part_value_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong wide part value must fail");
    assert!(
        part_value_error.contains("PackedSelect:4:u[Ref:8:u[wrong_data]")
            && part_value_error.contains("PackedSelect:4:u[Ref:8:u[wdata]"),
        "unexpected wide part value error: {part_value_error}"
    );

    let mut direct_simulator = Simulator::new(&direct).expect("create direct wide-array simulator");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize direct clock");
    direct_simulator
        .set_input("addr", &LogicWord::from_u64(3, 4))
        .expect("select direct element");
    direct_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set direct part start");
    direct_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x5a))
        .expect("set direct data");
    assert_eq!(direct_simulator.read("whole").unwrap().to_u64(), Some(0x34));
    assert_eq!(
        direct_simulator.read("indexed_whole").unwrap().to_u64(),
        Some(0x34)
    );
    assert_eq!(direct_simulator.read("part").unwrap().to_u64(), Some(0x3));
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create direct posedge");
    assert_eq!(direct_simulator.read("whole").unwrap().to_u64(), Some(0xaa));
    assert_eq!(
        direct_simulator.read("indexed_whole").unwrap().to_u64(),
        Some(0xaa)
    );
    assert_eq!(direct_simulator.read("part").unwrap().to_u64(), Some(0xa));

    let mut bounded_simulator =
        Simulator::new(&bounded).expect("create bounded wide-array simulator");
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize bounded clock");
    bounded_simulator
        .set_input("addr", &LogicWord::from_u64(3, 4))
        .expect("select bounded element");
    bounded_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set bounded part start");
    bounded_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x5a))
        .expect("set bounded data");
    assert_eq!(
        bounded_simulator.read("whole").unwrap().to_u64(),
        Some(0x34)
    );
    assert_eq!(
        bounded_simulator.read("indexed_whole").unwrap().to_u64(),
        Some(0x34)
    );
    assert_eq!(bounded_simulator.read("part").unwrap().to_u64(), Some(0x3));
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create bounded posedge");
    assert_eq!(
        bounded_simulator.read("whole").unwrap().to_u64(),
        Some(0xaa)
    );
    assert_eq!(
        bounded_simulator.read("indexed_whole").unwrap().to_u64(),
        Some(0xaa)
    );
    assert_eq!(bounded_simulator.read("part").unwrap().to_u64(), Some(0xa));
}

#[test]
fn slang_and_bounded_paths_lower_array_element_simple_ranges() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("array-simple-range");
    let source_path = root.join("simple-range.sv");
    std::fs::write(
        &source_path,
        r#"
module simple_range(input logic [1:0] addr, output logic [3:0] y);
  logic [7:0] mem [0:0];
  initial begin
    mem[0] = 8'h9c;
    mem[0][2:1] = 2'b01;
  end
  assign y = mem[addr][3:0];
endmodule
"#,
    )
    .expect("write array-element simple-range source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("simple_range"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower array-element simple range");
    let bounded = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("simple_range"),
            &PreprocessOptions::default(),
        )
        .expect("lower array-element simple range through bounded path");
    let bounded_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("simple_range"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize bounded array-element AST");
    let mut bounded_summary = slang
        .summarize_ast_json(&bounded_json)
        .expect("summarize bounded array-element AST");
    bounded_summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect("exact constant-index array fingerprints should match");
    if let Some(target) = bounded_summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "y")
    {
        target.rhs.operands[0].operands[1].symbol = Some("wrong_addr".into());
    }
    let simple_range_index_error = bounded_summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong dynamic array simple-range selector must fail");
    assert!(
        simple_range_index_error.contains("Ref:2:u[wrong_addr]")
            && simple_range_index_error.contains("Ref:2:u[addr]")
            && simple_range_index_error.contains("Cond:8:u["),
        "unexpected simple-range selector error: {simple_range_index_error}"
    );
    if let Some(target) = bounded_summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "y")
    {
        target.rhs.operands[0].operands[1].symbol = Some("addr".into());
        target.rhs.type_width = Some(3);
        target.rhs.operands[1].literal = Some("32:010".into());
    }
    let simple_range_width_error = bounded_summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong dynamic array simple-range width must fail");
    assert!(
        simple_range_width_error.contains("Const:3:u[3:111]")
            && simple_range_width_error.contains("Const:4:u[4:1111]"),
        "unexpected simple-range width error: {simple_range_width_error}"
    );
    if let Some(target) = bounded_summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "y")
    {
        target.rhs.type_width = Some(4);
        target.rhs.operands[1].literal = Some("32:011".into());
    }
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| block.assignments.first_mut())
    {
        assignment.rhs.operands[0].literal = Some("8:10100100".into());
    }
    let whole_element_error = bounded_summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant-index whole-element RHS must fail");
    assert!(
        whole_element_error.contains("Const:8:u[8:10100100]")
            && whole_element_error.contains("Const:8:u[8:10011100]"),
        "unexpected whole-element error: {whole_element_error}"
    );
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| block.assignments.first_mut())
    {
        assignment.rhs.operands[0].literal = Some("8:10011100".into());
    }
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| block.assignments.get_mut(1))
    {
        assignment.rhs.operands[0].literal = Some("2:10".into());
    }
    let range_error = bounded_summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant-index array range RHS must fail");
    assert!(
        range_error.contains("Const:2:u[2:10]") && range_error.contains("Const:2:u[2:01]"),
        "unexpected array-range error: {range_error}"
    );
    assert_eq!(direct.memories.len(), 1);

    let mut direct_simulator = Simulator::new(&direct).expect("create direct simulator");
    direct_simulator
        .set_input("addr", &LogicWord::from_u64(2, 0))
        .expect("set direct address");
    assert_eq!(direct_simulator.read("y").unwrap().to_u64(), Some(0b1010));

    let mut bounded_simulator = Simulator::new(&bounded).expect("create bounded simulator");
    bounded_simulator
        .set_input("addr", &LogicWord::from_u64(2, 0))
        .expect("set bounded address");
    assert_eq!(bounded_simulator.read("y").unwrap().to_u64(), Some(0b1010));
}

#[test]
fn slang_ast_direct_lowering_uses_multidimensional_sparse_memory() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory2d");
    let source_path = root.join("memory2d.sv");
    std::fs::write(
        &source_path,
        r#"
module memory2d(
  input logic clk,
  input logic [1:0] x,
  input logic [2:0] y,
  input logic [7:0] wdata,
  output logic [7:0] q,
  output logic [3:0] p
);
  logic [7:0] mem [0:1][2:3];
  initial begin
    mem[0][2] = 8'h12;
    mem[1][3] = 8'h34;
  end
  always_comb q = mem[x][y];
  assign p = mem[x][y][3:0];
  always @(posedge clk) mem[x][y] <= wdata;
endmodule
"#,
    )
    .expect("write multidimensional sparse-memory source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory2d"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower multidimensional sparse memory");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("memory2d"),
            &PreprocessOptions::default(),
        )
        .expect("lower multidimensional memory through the bounded path");
    assert_eq!(direct.memories.len(), 1);
    assert_eq!(direct.memories[0].dimensions.len(), 2);
    assert_eq!(direct.memories[0].flat_length, 4);
    assert_eq!(
        direct.memories[0].banking,
        eda_core::ir::MemoryBanking { count: 2, depth: 2 }
    );
    assert_eq!(direct.n_nets, 27);
    let direct_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory2d"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize multidimensional-memory AST");
    let direct_summary = slang
        .summarize_ast_json(&direct_json)
        .expect("summarize multidimensional-memory AST");
    direct_summary
        .validate_against_design(&direct)
        .expect("exact multidimensional memory fingerprints should match");
    let mut bounded_summary = direct_summary.clone();
    bounded_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect("exact dynamic multidimensional whole-element fingerprint should match");
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .target_names
                    .first()
                    .is_some_and(|name| name == "q")
            })
        })
    {
        assignment.rhs.operands[0].operands[1].symbol = Some("wrong_x".into());
    }
    let bounded_read_index_error = bounded_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong bounded multidimensional read index must fail");
    assert!(
        bounded_read_index_error.contains("Ref:2:u[wrong_x]")
            && bounded_read_index_error.contains("Ref:2:u[x]")
            && bounded_read_index_error.contains("Cond:32:u["),
        "unexpected bounded multidimensional read error: {bounded_read_index_error}"
    );
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block.assignments.iter_mut().find(|assignment| {
                assignment
                    .target_names
                    .first()
                    .is_some_and(|name| name == "q")
            })
        })
    {
        assignment.rhs.operands[0].operands[1].symbol = Some("x".into());
    }
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find(|assignment| assignment.dynamic_array_lvalue_indexes.len() == 2)
        })
    {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("wrong_x".into());
    }
    let bounded_first_index_error = bounded_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong bounded first multidimensional index must fail");
    assert!(
        bounded_first_index_error.contains("Ref:2:u[wrong_x]")
            && bounded_first_index_error.contains("Ref:2:u[x]")
            && bounded_first_index_error.contains("Cond:32:u["),
        "unexpected bounded first index error: {bounded_first_index_error}"
    );
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find(|assignment| assignment.dynamic_array_lvalue_indexes.len() == 2)
        })
    {
        assignment.dynamic_array_lvalue_indexes[0].symbol = Some("x".into());
        assignment.dynamic_array_lvalue_indexes[1].symbol = Some("wrong_y".into());
    }
    let bounded_second_index_error = bounded_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong bounded second multidimensional index must fail");
    assert!(
        bounded_second_index_error.contains("Ref:3:u[wrong_y]")
            && bounded_second_index_error.contains("Ref:3:u[y]")
            && bounded_second_index_error.contains("Cond:32:u["),
        "unexpected bounded second index error: {bounded_second_index_error}"
    );
    if let Some(assignment) = bounded_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find(|assignment| assignment.dynamic_array_lvalue_indexes.len() == 2)
        })
    {
        assignment.dynamic_array_lvalue_indexes[1].symbol = Some("y".into());
        assignment.rhs.symbol = Some("wrong_data".into());
    }
    let bounded_value_error = bounded_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong bounded multidimensional value must fail");
    assert!(
        bounded_value_error.contains("Ref:8:u[wrong_data]")
            && bounded_value_error.contains("Ref:8:u[wdata]")
            && bounded_value_error.contains("Cond:32:u["),
        "unexpected bounded value error: {bounded_value_error}"
    );

    let mut wrong_first_index = direct_summary.clone();
    if let Some(assignment) = wrong_first_index
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        assignment.rhs.operands[0].operands[0].operands[1].symbol = Some("wrong_x".into());
    }
    let first_index_error = wrong_first_index
        .validate_against_design(&direct)
        .expect_err("wrong first multidimensional-memory index must fail");
    assert!(
        first_index_error.contains("Ref:2:u[wrong_x]")
            && first_index_error.contains("Ref:2:u[x]")
            && first_index_error.contains("MemoryReadPart:4:u[mem,"),
        "unexpected first multidimensional-memory index error: {first_index_error}"
    );

    let mut wrong_second_index = direct_summary;
    if let Some(target) = wrong_second_index
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        target.rhs.operands[0].operands[1].symbol = Some("wrong_y".into());
    }
    let second_index_error = wrong_second_index
        .validate_against_design(&direct)
        .expect_err("wrong second multidimensional-memory index must fail");
    assert!(
        second_index_error.contains("Ref:3:u[wrong_y]")
            && second_index_error.contains("Ref:3:u[y]")
            && second_index_error.contains("MemoryReadPart:4:u[mem,"),
        "unexpected second multidimensional-memory index error: {second_index_error}"
    );

    let mut direct_simulator = Simulator::new(&direct).expect("create direct 2D simulator");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize direct clock");
    direct_simulator
        .set_input("x", &LogicWord::from_u64(2, 0))
        .expect("set first direct index");
    direct_simulator
        .set_input("y", &LogicWord::from_u64(3, 2))
        .expect("set second direct index");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x12));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0x2));
    direct_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x5a))
        .expect("set direct 2D write data");
    direct_simulator
        .set_input("x", &LogicWord::from_u64(2, 1))
        .expect("update first direct index");
    direct_simulator
        .set_input("y", &LogicWord::from_u64(3, 3))
        .expect("update second direct index");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0x4));
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create direct 2D posedge");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x5a));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0xa));

    let mut reference_simulator = Simulator::new(&reference).expect("create bounded 2D simulator");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize bounded clock");
    reference_simulator
        .set_input("x", &LogicWord::from_u64(2, 0))
        .expect("set first bounded index");
    reference_simulator
        .set_input("y", &LogicWord::from_u64(3, 2))
        .expect("set second bounded index");
    assert_eq!(reference_simulator.read("q").unwrap().to_u64(), Some(0x12));
    assert_eq!(reference_simulator.read("p").unwrap().to_u64(), Some(0x2));
    reference_simulator
        .set_input("x", &LogicWord::from_u64(2, 1))
        .expect("update first bounded index");
    reference_simulator
        .set_input("y", &LogicWord::from_u64(3, 3))
        .expect("update second bounded index");
    assert_eq!(reference_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(reference_simulator.read("p").unwrap().to_u64(), Some(0x4));
    reference_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x5a))
        .expect("set bounded 2D write data");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create bounded 2D posedge");
    assert_eq!(reference_simulator.read("q").unwrap().to_u64(), Some(0x5a));
    assert_eq!(reference_simulator.read("p").unwrap().to_u64(), Some(0xa));
}

#[test]
fn slang_ast_direct_lowering_uses_multidimensional_indexed_part_writes() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory2d-parts");
    let source_path = root.join("memory2d-parts.sv");
    std::fs::write(
        &source_path,
        r#"
module memory2d_parts(
  input logic clk,
  input logic [1:0] x,
  input logic [2:0] y,
  input logic [2:0] start,
  input logic [7:0] wdata,
  output logic [7:0] q,
  output logic [3:0] p
);
  logic [7:0] mem [0:1][2:3];
  initial begin
    mem[1][3] = 8'h34;
  end
  assign q = mem[x][y];
  assign p = mem[x][y][start +: 4];
  always @(posedge clk) mem[x][y][start +: 4] <= wdata[3:0];
endmodule
"#,
    )
    .expect("write multidimensional indexed part-write source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory2d_parts"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower multidimensional indexed part write");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("memory2d_parts"),
            &PreprocessOptions::default(),
        )
        .expect("lower multidimensional indexed part write through bounded path");
    let reference_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory2d_parts"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize multidimensional indexed part AST");
    let mut reference_summary = slang
        .summarize_ast_json(&reference_json)
        .expect("summarize multidimensional indexed part AST");
    reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect("exact dynamic multidimensional part fingerprint should match");
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.indexes[0].symbol = Some("wrong_x".into());
    }
    let first_index_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic first multidimensional index must fail");
    assert!(
        first_index_error.contains("Ref:2:u[wrong_x]")
            && first_index_error.contains("Ref:2:u[x]")
            && first_index_error.contains("GuardedArrayPartWrite:4:u["),
        "unexpected dynamic first index error: {first_index_error}"
    );
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.indexes[0].symbol = Some("x".into());
        part.indexes[1].symbol = Some("wrong_y".into());
    }
    let second_index_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic second multidimensional index must fail");
    assert!(
        second_index_error.contains("Ref:3:u[wrong_y]")
            && second_index_error.contains("Ref:3:u[y]")
            && second_index_error.contains("GuardedArrayPartWrite:4:u["),
        "unexpected dynamic second index error: {second_index_error}"
    );
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.indexes[1].symbol = Some("y".into());
        part.start.symbol = Some("wrong_start".into());
    }
    let start_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic multidimensional part start must fail");
    assert!(
        start_error.contains("Ref:3:u[wrong_start]") && start_error.contains("Ref:3:u[start]"),
        "unexpected dynamic part start error: {start_error}"
    );
    if let Some(part) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find_map(|assignment| assignment.array_part_lvalue.as_mut())
        })
    {
        part.start.symbol = Some("start".into());
        part.width = 3;
    }
    let width_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic multidimensional part width must fail closed");
    assert!(
        width_error.contains("could not fingerprint array part lvalue 'mem'"),
        "unexpected dynamic part width error: {width_error}"
    );
    if let Some(assignment) = reference_summary
        .procedural_blocks
        .iter_mut()
        .find_map(|block| {
            block
                .assignments
                .iter_mut()
                .find(|assignment| assignment.array_part_lvalue.is_some())
        })
    {
        assignment.array_part_lvalue.as_mut().unwrap().width = 4;
        assignment.rhs.operands[0].symbol = Some("wrong_data".into());
    }
    let value_error = reference_summary
        .validate_against_design_legacy_compatibility(&reference)
        .expect_err("wrong dynamic multidimensional part value must fail");
    assert!(
        value_error.contains("PackedSelect:4:u[Ref:8:u[wrong_data]")
            && value_error.contains("PackedSelect:4:u[Ref:8:u[wdata]"),
        "unexpected dynamic part value error: {value_error}"
    );
    assert_eq!(direct.memories.len(), 1);
    assert_eq!(direct.memories[0].dimensions.len(), 2);

    let mut direct_simulator = Simulator::new(&direct).expect("create direct part-write simulator");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize direct clock");
    direct_simulator
        .set_input("x", &LogicWord::from_u64(2, 1))
        .expect("set direct first index");
    direct_simulator
        .set_input("y", &LogicWord::from_u64(3, 3))
        .expect("set direct second index");
    direct_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set direct part start");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0x3));
    direct_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x0a))
        .expect("set direct part data");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create direct posedge");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0xa4));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0xa));

    let mut reference_simulator =
        Simulator::new(&reference).expect("create bounded part-write simulator");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize bounded clock");
    reference_simulator
        .set_input("x", &LogicWord::from_u64(2, 1))
        .expect("set bounded first index");
    reference_simulator
        .set_input("y", &LogicWord::from_u64(3, 3))
        .expect("set bounded second index");
    reference_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set bounded part start");
    assert_eq!(reference_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(reference_simulator.read("p").unwrap().to_u64(), Some(0x3));
    reference_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x0a))
        .expect("set bounded part data");
    reference_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create bounded posedge");
    assert_eq!(reference_simulator.read("q").unwrap().to_u64(), Some(0xa4));
    assert_eq!(reference_simulator.read("p").unwrap().to_u64(), Some(0xa));
}

#[test]
fn slang_ast_summary_uses_multidimensional_array_part_layouts() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory2d-constant-parts");
    let source_path = root.join("memory2d_constant_parts.sv");
    std::fs::write(
        &source_path,
        r#"
module memory2d_constant_parts(
  input logic clk,
  input logic [2:0] start,
  input logic [7:0] wdata,
  output logic [7:0] q,
  output logic [3:0] p,
  output logic [3:0] r
);
  logic [7:0] mem [0:1][2:3];
  initial begin
    mem[1][3] = 8'h34;
  end
  always @(posedge clk) mem[1][3][start +: 4] <= wdata[3:0];
  assign q = mem[1][3];
  assign p = mem[1][3][start +: 4];
  assign r = mem[1][3][5:2];
endmodule
"#,
    )
    .expect("write multidimensional constant part-write source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory2d_constant_parts"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower multidimensional constant part write");
    let bounded = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("memory2d_constant_parts"),
            &PreprocessOptions::default(),
        )
        .expect("lower multidimensional constant part write through bounded path");
    let json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("memory2d_constant_parts"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize multidimensional constant part AST");
    let mut summary = slang
        .summarize_ast_json(&json)
        .expect("summarize multidimensional constant part AST");
    summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect("exact multidimensional constant part fingerprint should match");

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "q")
    {
        target.rhs.operands[0].operands[1].literal =
            Some("32:00000000000000000000000000000000".into());
    }
    let constant_read_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant multidimensional array read index must fail");
    assert!(
        constant_read_error.contains("Range:15:8") && constant_read_error.contains("Range:31:24"),
        "unexpected constant read error: {constant_read_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "q")
    {
        target.rhs.operands[0].operands[1].literal =
            Some("32:00000000000000000000000000000001".into());
    }

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        target.rhs.operands[1].symbol = Some("wrong_start".into());
    }
    let constant_part_start_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant multidimensional array part-read start must fail");
    assert!(
        constant_part_start_error.contains("Ref:3:u[wrong_start]")
            && constant_part_start_error.contains("Ref:3:u[start]")
            && constant_part_start_error.contains("Cond:8:u["),
        "unexpected constant part-read start error: {constant_part_start_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        target.rhs.operands[1].symbol = Some("start".into());
        target.rhs.operands[0].operands[1].literal =
            Some("32:00000000000000000000000000000010".into());
    }
    let constant_part_index_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant multidimensional array part-read index must fail");
    assert!(
        constant_part_index_error.contains("Range:23:16")
            && constant_part_index_error.contains("Range:31:24"),
        "unexpected constant part-read index error: {constant_part_index_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        target.rhs.operands[0].operands[1].literal =
            Some("32:00000000000000000000000000000011".into());
        target.rhs.type_width = Some(3);
        target.rhs.operands[2].literal = Some("32:011".into());
    }
    let constant_part_width_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant multidimensional array part-read width must fail");
    assert!(
        constant_part_width_error.contains("Const:3:u[3:111]")
            && constant_part_width_error.contains("Const:4:u[4:1111]"),
        "unexpected constant part-read width error: {constant_part_width_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "p")
    {
        target.rhs.type_width = Some(4);
        target.rhs.operands[2].literal = Some("32:00000000000000000000000000000100".into());
    }

    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "r")
    {
        target.rhs.type_width = Some(3);
        target.rhs.operands[1].literal = Some("32:100".into());
    }
    let constant_simple_range_width_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong constant multidimensional array simple-range width must fail");
    assert!(
        constant_simple_range_width_error.contains("MemoryReadPart:3:u[mem")
            && constant_simple_range_width_error.contains("Cond:8:u["),
        "unexpected constant simple-range width error: {constant_simple_range_width_error}"
    );
    if let Some(target) = summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "r")
    {
        target.rhs.type_width = Some(4);
        target.rhs.operands[1].literal = Some("32:00000000000000000000000000000101".into());
    }

    if let Some(part) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find_map(|assignment| assignment.array_part_lvalue.as_mut())
    }) {
        part.indexes[0].literal = Some("32:00000000000000000000000000000000".into());
    }
    let first_index_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong first multidimensional part index must fail");
    assert!(
        first_index_error.contains("Offset:8") && first_index_error.contains("Offset:24"),
        "unexpected first index error: {first_index_error}"
    );

    if let Some(part) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find_map(|assignment| assignment.array_part_lvalue.as_mut())
    }) {
        part.indexes[0].literal = Some("32:00000000000000000000000000000001".into());
        part.indexes[1].literal = Some("32:00000000000000000000000000000010".into());
    }
    let second_index_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong second multidimensional part index must fail");
    assert!(
        second_index_error.contains("Offset:16") && second_index_error.contains("Offset:24"),
        "unexpected second index error: {second_index_error}"
    );

    if let Some(part) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find_map(|assignment| assignment.array_part_lvalue.as_mut())
    }) {
        part.indexes[1].literal = Some("32:00000000000000000000000000000011".into());
        part.start.symbol = Some("wrong_start".into());
    }
    let start_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong multidimensional part start must fail");
    assert!(
        start_error.contains("Ref:3:u[wrong_start]") && start_error.contains("Ref:3:u[start]"),
        "unexpected multidimensional part start error: {start_error}"
    );

    if let Some(part) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find_map(|assignment| assignment.array_part_lvalue.as_mut())
    }) {
        part.start.symbol = Some("start".into());
        part.width = 3;
    }
    let width_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong multidimensional part width must fail closed");
    assert!(
        width_error.contains("could not fingerprint array part lvalue 'mem'"),
        "unexpected multidimensional part width error: {width_error}"
    );

    if let Some(assignment) = summary.procedural_blocks.iter_mut().find_map(|block| {
        block
            .assignments
            .iter_mut()
            .find(|assignment| assignment.array_part_lvalue.is_some())
    }) {
        assignment.array_part_lvalue.as_mut().unwrap().width = 4;
        assignment.rhs.operands[0].symbol = Some("wrong_data".into());
    }
    let value_error = summary
        .validate_against_design_legacy_compatibility(&bounded)
        .expect_err("wrong multidimensional part value must fail");
    assert!(
        value_error.contains("PackedSelect:4:u[Ref:8:u[wrong_data]")
            && value_error.contains("PackedSelect:4:u[Ref:8:u[wdata]"),
        "unexpected multidimensional part value error: {value_error}"
    );

    let mut direct_simulator =
        Simulator::new(&direct).expect("create direct multidimensional part simulator");
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize direct clock");
    direct_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set direct part start");
    direct_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x0a))
        .expect("set direct part data");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0x3));
    assert_eq!(direct_simulator.read("r").unwrap().to_u64(), Some(0xd));
    direct_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create direct posedge");
    assert_eq!(direct_simulator.read("q").unwrap().to_u64(), Some(0xa4));
    assert_eq!(direct_simulator.read("p").unwrap().to_u64(), Some(0xa));
    assert_eq!(direct_simulator.read("r").unwrap().to_u64(), Some(0x9));

    let mut bounded_simulator =
        Simulator::new(&bounded).expect("create bounded multidimensional part simulator");
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 0))
        .expect("initialize bounded clock");
    bounded_simulator
        .set_input("start", &LogicWord::from_u64(3, 4))
        .expect("set bounded part start");
    bounded_simulator
        .set_input("wdata", &LogicWord::from_u64(8, 0x0a))
        .expect("set bounded part data");
    assert_eq!(bounded_simulator.read("q").unwrap().to_u64(), Some(0x34));
    assert_eq!(bounded_simulator.read("p").unwrap().to_u64(), Some(0x3));
    assert_eq!(bounded_simulator.read("r").unwrap().to_u64(), Some(0xd));
    bounded_simulator
        .set_input("clk", &LogicWord::from_u64(1, 1))
        .expect("create bounded posedge");
    assert_eq!(bounded_simulator.read("q").unwrap().to_u64(), Some(0xa4));
    assert_eq!(bounded_simulator.read("p").unwrap().to_u64(), Some(0xa));
    assert_eq!(bounded_simulator.read("r").unwrap().to_u64(), Some(0x9));
}

#[test]
fn slang_ast_direct_lowering_shares_child_sparse_memory_ports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory-port");
    let source_path = root.join("memory-port.sv");
    std::fs::write(
        &source_path,
        r#"
module child(
  inout wire logic [7:0] memory [0:4095],
  output logic [7:0] q
);
  assign q = memory[2];
endmodule

module top(
  input logic [7:0] din,
  output logic [7:0] child_q,
  output logic [7:0] parent_q
);
  wire logic [7:0] memory [0:4095];
  child u (
    .memory(memory),
    .q(child_q)
  );
  assign memory[2] = din;
  assign parent_q = memory[2];
endmodule
"#,
    )
    .expect("write shared sparse-memory port source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower shared sparse-memory port");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("lower shared sparse-memory port through bounded path");
    assert_eq!(direct.memories.len(), 2);
    assert_eq!(direct.memory_connections.len(), 1);
    assert_eq!(direct.array_connections.len(), 0);
    assert_eq!(direct.memory_connections[0].child, 1);
    assert_eq!(direct.memory_connections[0].parent, 0);
    assert_eq!(reference.memories.len(), 2);
    assert_eq!(reference.memory_connections.len(), 1);
    assert_eq!(direct.memories[0].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(direct.memories[1].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(reference.memories[0].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(reference.memories[1].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(
        direct.memories[0].template,
        eda_core::ir::MemoryTemplate::AsyncRam
    );
    assert_eq!(
        direct.memories[1].template,
        eda_core::ir::MemoryTemplate::AsyncRam
    );
    assert_eq!(
        reference.memories[0].template,
        eda_core::ir::MemoryTemplate::AsyncRam
    );
    assert_eq!(
        reference.memories[1].template,
        eda_core::ir::MemoryTemplate::AsyncRam
    );
    let mut direct_simulator =
        Simulator::new(&direct).expect("create direct shared-memory simulator");
    direct_simulator
        .set_input("din", &LogicWord::from_u64(8, 0xa7))
        .expect("set direct shared data");
    assert_eq!(
        direct_simulator.read("child_q").unwrap().to_u64(),
        Some(0xa7)
    );
    assert_eq!(
        direct_simulator.read("parent_q").unwrap().to_u64(),
        Some(0xa7)
    );

    let mut reference_simulator =
        Simulator::new(&reference).expect("create bounded shared-memory simulator");
    reference_simulator
        .set_input("din", &LogicWord::from_u64(8, 0xa7))
        .expect("set bounded shared data");
    assert_eq!(
        reference_simulator.read("child_q").unwrap().to_u64(),
        Some(0xa7)
    );
    assert_eq!(
        reference_simulator.read("parent_q").unwrap().to_u64(),
        Some(0xa7)
    );
}

#[test]
fn slang_ast_direct_and_bounded_paths_share_nested_ordinary_array_ports() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-nested-ordinary-array-ports");
    let source_path = root.join("nested_ordinary_array_ports.sv");
    std::fs::write(
        &source_path,
        r#"
module leaf(
  input wire logic [7:0] source [0:3],
  output logic [7:0] destination [0:3],
  output logic [7:0] source_observed
);
  initial begin
    destination[2] = 8'h5a;
  end
  assign source_observed = source[2];
endmodule

module middle(
  input wire logic [7:0] pass_source [0:3],
  output logic [7:0] pass_destination [0:3],
  output logic [7:0] middle_observed
);
  leaf u (
    .source(pass_source),
    .destination(pass_destination),
    .source_observed(middle_observed)
  );
endmodule

module top(
  output logic [7:0] source_observed,
  output logic [7:0] destination_observed
);
  logic [7:0] source [0:3];
  logic [7:0] destination [0:3];

  initial begin
    source[2] = 8'h3c;
  end

  middle u (
    .pass_source(source),
    .pass_destination(destination),
    .middle_observed(source_observed)
  );
  assign destination_observed = destination[2];
endmodule
"#,
    )
    .expect("write nested ordinary-array port source");

    let direct = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower nested ordinary-array ports");
    let reference = slang
        .compile_files_bounded(
            std::slice::from_ref(&source_path),
            Some("top"),
            &PreprocessOptions::default(),
        )
        .expect("lower nested ordinary-array ports through bounded path");

    assert_eq!(direct.memories.len(), 6);
    assert_eq!(direct.memory_connections.len(), 0);
    assert_eq!(direct.array_connections.len(), 4);
    assert!(direct
        .array_connections
        .contains(&eda_core::ir::ArrayConnection {
            child: 4,
            parent: 2
        }));
    assert!(direct
        .array_connections
        .contains(&eda_core::ir::ArrayConnection {
            child: 5,
            parent: 3
        }));
    assert!(direct
        .array_connections
        .contains(&eda_core::ir::ArrayConnection {
            child: 2,
            parent: 0
        }));
    assert!(direct
        .array_connections
        .contains(&eda_core::ir::ArrayConnection {
            child: 3,
            parent: 1
        }));
    assert!(direct
        .memories
        .iter()
        .all(|memory| memory.storage == eda_core::ir::MemoryStorage::Ordinary));

    let mut direct_simulator =
        Simulator::new(&direct).expect("create direct nested ordinary-array simulator");
    direct_simulator
        .run_until(0)
        .expect("settle direct nested ordinary arrays");
    assert_eq!(
        direct_simulator.read("source_observed").unwrap().to_u64(),
        Some(0x3c),
        "parent initial value must flow through two child input aliases"
    );
    assert_eq!(
        direct_simulator
            .read("destination_observed")
            .unwrap()
            .to_u64(),
        Some(0x5a),
        "leaf initial value must flow through two child output aliases"
    );

    let mut reference_simulator =
        Simulator::new(&reference).expect("create bounded nested ordinary-array simulator");
    reference_simulator
        .run_until(0)
        .expect("settle bounded nested ordinary arrays");
    assert_eq!(
        reference_simulator
            .read("source_observed")
            .unwrap()
            .to_u64(),
        Some(0x3c)
    );
    assert_eq!(
        reference_simulator
            .read("destination_observed")
            .unwrap()
            .to_u64(),
        Some(0x5a)
    );
}

#[test]
fn slang_ast_direct_lowering_initializes_multidimensional_ordinary_array() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-memory-init");
    let source_path = root.join("memory-init.sv");
    std::fs::write(
        &source_path,
        r#"
module memory_init(
  output logic [7:0] first,
  output logic [7:0] middle,
  output logic [7:0] last
);
  logic [7:0] mem [0:1][0:2] = '{
    '{8'h01, 8'h02, 8'h03},
    '{8'h04, 8'h05, 8'h06}
  };
  assign first = mem[0][0];
  assign middle = mem[0][2];
  assign last = mem[1][2];
endmodule
"#,
    )
    .expect("write sparse-memory initializer source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("memory_init"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower sparse-memory initializer");
    assert_eq!(design.memories.len(), 1);
    assert_eq!(
        design.memories[0].storage,
        eda_core::ir::MemoryStorage::Ordinary
    );
    assert_eq!(design.memories[0].dimensions.len(), 2);
    assert_eq!(design.memories[0].flat_length, 6);
    assert_eq!(design.memories[0].kind, eda_core::ir::MemoryKind::Ram);
    assert_eq!(
        design.memories[0].template,
        eda_core::ir::MemoryTemplate::Unmapped
    );
    assert_eq!(design.memories[0].write_mask, None);
    assert_eq!(design.memories[0].byte_enable, None);
    assert_eq!(
        design.memories[0].banking,
        eda_core::ir::MemoryBanking::default()
    );
    assert_eq!(design.initials.len(), 1);

    let mut simulator = Simulator::new(&design).expect("create initializer simulator");
    simulator
        .run_until(0)
        .expect("settle sparse-memory initializers");
    assert_eq!(simulator.read("first").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("middle").unwrap().to_u64(), Some(3));
    assert_eq!(simulator.read("last").unwrap().to_u64(), Some(6));
}

