#[test]
fn slang_ast_direct_lowering_supports_interface_unpacked_struct_members() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-interface-unpacked-struct");
    let source_path = root.join("interface_unpacked_struct.sv");
    std::fs::write(
        &source_path,
        r#"
interface bus_if(input logic clk);
  typedef struct {
    logic [7:0] value;
  } payload_t;

  typedef struct {
    logic [3:0] tag;
    logic valid;
  } metadata_t;

  typedef struct {
    payload_t payload;
    metadata_t metadata;
  } packet_t;

  packet_t packet;
  modport producer(output packet);
endinterface

module producer(
  bus_if.producer bus,
  input logic [7:0] value,
  input logic [3:0] tag
);
  assign bus.packet.payload.value = value;
  assign bus.packet.metadata.tag = tag;
  assign bus.packet.metadata.valid = 1'b1;
endmodule

module interface_unpacked_struct_top(
  input logic clk,
  input logic [7:0] value,
  input logic [3:0] tag,
  output logic [7:0] observed_value,
  output logic [3:0] observed_tag,
  output logic observed_valid
);
  bus_if bus(.clk(clk));
  producer producer_u(.bus(bus), .value(value), .tag(tag));
  assign observed_value = bus.packet.payload.value;
  assign observed_tag = bus.packet.metadata.tag;
  assign observed_valid = bus.packet.metadata.valid;
endmodule
"#,
    )
    .expect("write interface unpacked-struct source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("interface_unpacked_struct_top"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower interface unpacked struct members");
    let unpacked_interface_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("interface_unpacked_struct_top"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize interface unpacked-struct AST");
    let mut unpacked_interface_summary = slang
        .summarize_ast_json(&unpacked_interface_json)
        .expect("summarize interface unpacked-struct AST");
    unpacked_interface_summary
        .validate_against_design(&design)
        .expect("exact interface unpacked-struct fingerprints should match");
    if let Some(target) = unpacked_interface_summary
        .continuous_targets
        .iter_mut()
        .find(|target| target.name == "observed_tag")
    {
        target.rhs.operands[0].member_path = vec!["payload".into()];
        target.rhs.operands[0].member_range = Some((7, 0));
    }
    let unpacked_interface_error = unpacked_interface_summary
        .validate_against_design(&design)
        .expect_err("wrong interface unpacked-struct member must fail");
    assert!(
        unpacked_interface_error.contains("Range:12:8")
            && unpacked_interface_error.contains("Range:7:0"),
        "unexpected interface unpacked-struct error: {unpacked_interface_error}"
    );
    assert!(design
        .net_decls
        .iter()
        .any(|declaration| declaration.name == "bus.packet" && declaration.width == 13));
    let mut simulator = Simulator::new(&design).expect("create unpacked-struct simulator");
    simulator
        .set_input("value", &LogicWord::from_u64(8, 0x9c))
        .unwrap();
    simulator
        .set_input("tag", &LogicWord::from_u64(4, 0b0110))
        .unwrap();
    assert_eq!(
        simulator.read("observed_value").unwrap().to_u64(),
        Some(0x9c)
    );
    assert_eq!(
        simulator.read("observed_tag").unwrap().to_u64(),
        Some(0b0110)
    );
    assert_eq!(simulator.read("observed_valid").unwrap().to_u64(), Some(1));
}

