    simulator.set_input("clk", &LogicWord::zero(1)).unwrap();
    simulator
        .set_input("reset", &LogicWord::from_u64(1, 1))
        .unwrap();
    simulator
        .set_input("go", &LogicWord::from_u64(1, 1))
        .unwrap();
