#[test]
fn slang_ast_direct_lowering_supports_event_arrays() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-event-array");
    let source_path = root.join("event_array.sv");
    std::fs::write(
        &source_path,
        r#"
module event_array(
  input logic go,
  input int index,
  input int wrong,
  output logic first,
  output logic second,
  output logic triggered_now,
  output logic triggered_later
);
  event events[2];
  initial begin
    first = 1'b0;
    second = 1'b0;
    wait (go);
    fork
      begin
        @(events[index]);
        #2 first = 1'b1;
        @(events[index]);
        second = 1'b1;
      end
      begin
        #1 ->events[wrong];
        #1 ->events[index];
        #3 ->events[index];
      end
    join
  end
  initial begin
    triggered_now = 1'b0;
    triggered_later = 1'b0;
    wait (go);
    ->events[index];
    triggered_now = events[index].triggered;
    #1 triggered_later = events[index].triggered;
  end
endmodule
"#,
    )
    .expect("write event-array source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("event_array"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower event array");
    assert_eq!(
        design
            .net_decls
            .iter()
            .find(|declaration| declaration.name == "events")
            .expect("event-array declaration")
            .width,
        2
    );
    let event_array_json = slang
        .ast_json_with_options(
            std::slice::from_ref(&source_path),
            Some("event_array"),
            &[],
            &PreprocessOptions::default(),
        )
        .expect("serialize event-array AST");
    let mut event_array_summary = slang
        .summarize_ast_json(&event_array_json)
        .expect("summarize event-array AST");
    event_array_summary
        .validate_against_design(&design)
        .expect("exact event-array fingerprints should match");
    fn replace_first_event_selector(expression: &mut eda_slang::SlangExpressionSummary) -> bool {
        if expression.kind == "ElementSelect" && expression.type_name == "event" {
            expression.operands[1].symbol = Some("wrong_selector".into());
            return true;
        }
        expression
            .operands
            .iter_mut()
            .any(replace_first_event_selector)
    }
    let mut replaced_event_selector = false;
    'assignments: for block in event_array_summary.procedural_blocks.iter_mut() {
        for assignment in block.assignments.iter_mut() {
            if assignment
                .target_names
                .first()
                .is_some_and(|name| name == "triggered_later")
                && replace_first_event_selector(&mut assignment.rhs)
            {
                replaced_event_selector = true;
                break 'assignments;
            }
        }
    }
    assert!(
        replaced_event_selector,
        "event-array selector was not found"
    );
    let wrong_event_selector_error = event_array_summary
        .validate_against_design(&design)
        .expect_err("wrong event-array selector must fail");
    assert!(
        wrong_event_selector_error.contains("Ref:32:s[wrong_selector]")
            && wrong_event_selector_error.contains("Ref:32:s[index]")
            && wrong_event_selector_error.contains("EventTriggered:1:u[events["),
        "unexpected event-array selector error: {wrong_event_selector_error}"
    );

    let mut simulator = Simulator::new(&design).expect("create event-array simulator");
    simulator
        .set_input("index", &LogicWord::from_u64(32, 0))
        .unwrap();
    simulator
        .set_input("wrong", &LogicWord::from_u64(32, 1))
        .unwrap();
    simulator
        .set_input("go", &LogicWord::from_u64(1, 1))
        .unwrap();
    simulator.run_until(10).unwrap();
    assert_eq!(simulator.read("triggered_now").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("triggered_later").unwrap().to_u64(), Some(0));
    assert_eq!(simulator.read("first").unwrap().to_u64(), Some(1));
    assert_eq!(simulator.read("second").unwrap().to_u64(), Some(1));
}

#[test]
fn slang_ast_direct_lowering_rejects_runtime_out_of_range_event_waits() {
    let Some(slang) = discover_slang_for_tests() else {
        return;
    };
    let root = temporary_directory("direct-ast-event-array-range");
    let source_path = root.join("event_array_range.sv");
    std::fs::write(
        &source_path,
        r#"
module event_array_range(input logic go, input int index);
  event events[2];
  initial begin
    wait (go);
    @(events[index]);
  end
endmodule
"#,
    )
    .expect("write out-of-range event-array source");

    let design = slang
        .compile_files_via_ast(
            std::slice::from_ref(&source_path),
            Some("event_array_range"),
            &PreprocessOptions::default(),
        )
        .expect("directly lower event-array range source");
    let mut simulator = Simulator::new(&design).expect("create event-array range simulator");
    simulator
        .set_input("index", &LogicWord::from_u64(32, 2))
        .unwrap();
    let error = simulator
        .set_input("go", &LogicWord::from_u64(1, 1))
        .expect_err("runtime out-of-range event waits must fail closed");
    assert!(
        error.contains("event array index is out of range"),
        "unexpected error: {error}"
    );
}

