    let nonconsecutive_path = root.join("unsupported_nonconsecutive_antecedent.sv");
    std::fs::write(
        &nonconsecutive_path,
        r#"
module unsupported_nonconsecutive_antecedent(
  input logic clk,
  input logic req,
  input logic grant
);
  assert property (@(posedge clk) req [=0:2] |-> grant);
endmodule
"#,
    )
